'use client';

import { useCallback, useEffect, useState } from 'react';
import { Check, ClipboardCheck, Eye, MessageSquare, X } from 'lucide-react';
import { StatusBadge } from '@/components/shared/status-badge';
import { useActionFeedback } from '@/components/providers/action-feedback';

type ReviewItem = {
  id: string;
  entityType: 'outlet' | 'product' | 'voucher';
  entityLabel: string;
  context: string;
  vendor_id: string;
  vendors?: { name?: string } | null;
  review_note?: string | null;
  created_at: string;
  display_id?: string | null;
};

const labels: Record<ReviewItem['entityType'], string> = {
  outlet: 'Outlet',
  product: 'Listing',
  voucher: 'Voucher',
};

export default function CatalogueReviewPage() {
  const { showFeedback } = useActionFeedback();
  const [items, setItems] = useState<ReviewItem[]>([]);
  const [filter, setFilter] = useState<'all' | ReviewItem['entityType']>('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [active, setActive] = useState<ReviewItem | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('/api/admin/catalogue/reviews', { cache: 'no-store' });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error?.message || 'Unable to load review queue');
      setItems(payload.data?.items ?? []);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'Unable to load review queue');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  async function review(item: ReviewItem, action: 'approve' | 'change_requested' | 'reject') {
    const note = action === 'approve' ? undefined : window.prompt(action === 'reject' ? 'Reason for rejection (at least 10 characters):' : 'What needs to be changed? (at least 10 characters)');
    if (action !== 'approve' && note === null) return;
    const trimmedNote = note?.trim();
    if (action !== 'approve' && (!trimmedNote || trimmedNote.length < 10)) {
      const message = `${action === 'reject' ? 'Reject' : 'Request changes'} requires a reason of at least 10 characters.`;
      setError(message);
      showFeedback('error', message);
      return;
    }
    setBusy(`${action}:${item.id}`);
    try {
      const response = await fetch('/api/admin/catalogue/reviews', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ entityType: item.entityType, entityId: item.id, action, note: trimmedNote }),
      });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error?.message || 'Review action failed');
      showFeedback('success', `${labels[item.entityType]} ${action === 'approve' ? 'approved' : action === 'reject' ? 'rejected' : 'returned for changes'}.`);
      setActive(null);
      await load();
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : 'Review action failed';
      setError(message);
      showFeedback('error', message);
    } finally {
      setBusy(null);
    }
  }

  const visible = filter === 'all' ? items : items.filter((item) => item.entityType === filter);
  const counts = {
    all: items.length,
    outlet: items.filter((item) => item.entityType === 'outlet').length,
    product: items.filter((item) => item.entityType === 'product').length,
    voucher: items.filter((item) => item.entityType === 'voucher').length,
  };

  return (
    <main className="min-h-full p-6 lg:p-10">
      <div className="mx-auto max-w-6xl space-y-6">
        <header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="inline-flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary"><ClipboardCheck size={15} /> Marketplace governance</p>
            <h1 className="mt-2 text-3xl font-bold tracking-tight text-gray-950">Catalogue review</h1>
            <p className="mt-1 text-sm text-gray-500">Review outlet, product and promotion changes before they become visible to customers.</p>
          </div>
          <div className="rounded-2xl border border-amber-100 bg-amber-50 px-4 py-3 text-right"><p className="text-xs font-semibold uppercase tracking-wider text-amber-700">Waiting</p><p className="mt-1 text-2xl font-bold text-amber-950">{items.length}</p></div>
        </header>

        <div className="flex flex-wrap gap-2 rounded-2xl border border-gray-100 bg-white p-2 shadow-sm">
          {(['all', 'outlet', 'product', 'voucher'] as const).map((value) => <button key={value} type="button" onClick={() => setFilter(value)} className={`rounded-xl px-4 py-2 text-sm font-semibold capitalize ${filter === value ? 'bg-gray-950 text-white' : 'text-gray-500 hover:bg-gray-50'}`}>{value === 'all' ? 'All items' : labels[value]} <span className="ml-1 text-xs opacity-70">{counts[value]}</span></button>)}
        </div>

        {error && <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
        <section className="overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-sm">
          <div className="hidden grid-cols-[110px_minmax(220px,1.5fr)_minmax(150px,1fr)_150px_90px] gap-4 border-b border-gray-100 bg-gray-50/70 px-5 py-3 text-xs font-semibold uppercase tracking-[0.12em] text-gray-500 md:grid"><span>Type</span><span>Submission</span><span>Vendor / location</span><span>Submitted</span><span className="text-right">Action</span></div>
          {loading ? <div className="space-y-3 p-5">{Array.from({ length: 5 }).map((_, index) => <div key={index} className="h-16 animate-pulse rounded-xl bg-gray-100" />)}</div> : visible.length === 0 ? <div className="px-6 py-20 text-center text-sm text-gray-400"><ClipboardCheck className="mx-auto mb-3 opacity-30" size={36} /><p>No content is waiting for review.</p></div> : <div className="divide-y divide-gray-100">{visible.map((item) => <article key={`${item.entityType}:${item.id}`} className="grid gap-3 px-4 py-4 md:grid-cols-[110px_minmax(220px,1.5fr)_minmax(150px,1fr)_150px_90px] md:items-center md:gap-4 md:px-5"><div><StatusBadge status={labels[item.entityType]} /></div><div className="min-w-0"><p className="truncate font-semibold text-gray-950">{item.entityLabel}</p><p className="mt-1 truncate text-xs text-gray-500">{item.display_id || item.id} · {item.context || 'No location provided'}</p></div><div className="min-w-0"><p className="truncate text-sm font-medium text-gray-700">{item.vendors?.name || 'Unknown vendor'}</p><p className="mt-1 text-xs text-amber-700">Pending review</p></div><div className="text-sm text-gray-500">{new Date(item.created_at).toLocaleDateString('en-MY', { day: '2-digit', month: 'short', year: 'numeric' })}</div><div className="flex justify-end gap-1"><button type="button" title="Open review" onClick={() => setActive(item)} className="rounded-lg p-2 text-gray-500 hover:bg-secondary hover:text-primary"><Eye size={16} /></button><button type="button" title="Approve" disabled={!!busy} onClick={() => void review(item, 'approve')} className="rounded-lg p-2 text-primary hover:bg-secondary disabled:opacity-40"><Check size={16} /></button></div></article>)}</div>}
        </section>
      </div>

      {active && <div className="fixed inset-0 z-50 bg-gray-950/25" onClick={() => setActive(null)}><aside onClick={(event) => event.stopPropagation()} className="absolute right-0 top-0 h-full w-full max-w-lg overflow-y-auto bg-white p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-primary">{labels[active.entityType]} review</p><h2 className="mt-1 text-xl font-bold text-gray-950">{active.entityLabel}</h2></div><button type="button" onClick={() => setActive(null)} className="rounded-lg p-2 text-gray-400 hover:bg-gray-100"><X size={18} /></button></div><div className="mt-6 space-y-3 text-sm"><div className="rounded-xl bg-gray-50 p-4"><p className="text-xs text-gray-500">Vendor</p><p className="mt-1 font-semibold text-gray-900">{active.vendors?.name || 'Unknown vendor'}</p></div><div className="rounded-xl bg-gray-50 p-4"><p className="text-xs text-gray-500">Reference</p><p className="mt-1 break-all font-mono text-xs text-gray-700">{active.display_id || active.id}</p><p className="mt-2 text-gray-600">{active.context || 'No location provided'}</p></div><div className="rounded-xl border border-violet-100 bg-violet-50 p-4 text-violet-900"><div className="flex items-center gap-2 font-semibold"><MessageSquare size={15} /> Review checklist</div><p className="mt-2 text-xs leading-5">Confirm the title, description, price, location, images and availability are accurate before approving.</p></div></div><div className="mt-8 grid gap-2 sm:grid-cols-3"><button type="button" disabled={!!busy} onClick={() => void review(active, 'approve')} className="rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white disabled:opacity-50">Approve</button><button type="button" disabled={!!busy} onClick={() => void review(active, 'change_requested')} className="rounded-xl border border-amber-200 px-4 py-3 text-sm font-semibold text-amber-700 disabled:opacity-50">Request changes</button><button type="button" disabled={!!busy} onClick={() => void review(active, 'reject')} className="rounded-xl border border-red-200 px-4 py-3 text-sm font-semibold text-red-700 disabled:opacity-50">Reject</button></div></aside></div>}
    </main>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Award, Clock, CheckCircle2, Play } from "lucide-react";
import { useAuth } from "@/components/providers/auth";
import { supabase } from "@/backend/supabase";
import { Button } from "@/components/ui/button";

interface PendingSummary {
  count: number;
  totalRM: number;
}

export default function AdminRewardsPage() {
  const { currentUser } = useAuth();
  const [pending, setPending]     = useState<PendingSummary | null>(null);
  const [loading, setLoading]     = useState(true);
  const [clearing, setClearing]   = useState(false);
  const [lastResult, setLastResult] = useState<{ confirmed: number } | null>(null);
  const [error, setError]         = useState("");

  async function loadPending() {
    setLoading(true);
    try {
      // Count attributions past their hold_until (ready to confirm)
      const { data: overdue } = await supabase
        .from("affiliate_attributions")
        .select("commission_amount")
        .eq("status", "pending")
        .lte("hold_until", new Date().toISOString());

      const rows = overdue ?? [];
      setPending({
        count:   rows.length,
        totalRM: rows.reduce((s, r) => s + Number(r.commission_amount), 0),
      });
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (currentUser) loadPending();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUser?.id]);

  async function runClearance() {
    setClearing(true);
    setError("");
    setLastResult(null);
    try {
      const res = await fetch("/api/admin/clear-earnings", { method: "POST" });
      const body = await res.json();
      if (!res.ok) {
        setError(body.error ?? "Clearance failed");
        return;
      }
      setLastResult({ confirmed: body.confirmed ?? 0 });
      await loadPending();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Unknown error");
    } finally {
      setClearing(false);
    }
  }

  return (
    <div className="max-w-2xl mx-auto px-6 py-10">
      <div className="flex items-center gap-3 mb-8">
        <Award size={22} className="text-primary" />
        <div>
          <h1 className="text-xl font-bold text-foreground">Reward Clearance</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Move affiliate commissions from pending hold into available earnings.
          </p>
        </div>
      </div>

      {/* Pending summary */}
      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="rounded-xl border border-border p-5">
          <p className="text-xs uppercase tracking-wide text-muted-foreground mb-1 flex items-center gap-1.5">
            <Clock size={12} /> Ready to confirm
          </p>
          {loading ? (
            <p className="text-2xl font-bold text-foreground">—</p>
          ) : (
            <p className="text-2xl font-bold text-foreground">{pending?.count ?? 0}</p>
          )}
          <p className="text-xs text-muted-foreground mt-1">attributions past hold window</p>
        </div>
        <div className="rounded-xl border border-border p-5">
          <p className="text-xs uppercase tracking-wide text-muted-foreground mb-1">Total value</p>
          {loading ? (
            <p className="text-2xl font-bold text-foreground">—</p>
          ) : (
            <p className="text-2xl font-bold text-foreground font-[family-name:var(--font-mono)]">
              RM {(pending?.totalRM ?? 0).toFixed(2)}
            </p>
          )}
          <p className="text-xs text-muted-foreground mt-1">to be moved to earnings_sen</p>
        </div>
      </div>

      {/* Run clearance */}
      <div className="rounded-xl border border-border p-6">
        <p className="text-sm font-semibold text-foreground mb-1">Run clearance now</p>
        <p className="text-xs text-muted-foreground mb-4">
          Processes all pending commissions whose hold window has expired.
          Vercel Cron also runs this automatically at midnight MYT.
        </p>

        {lastResult && (
          <div className="flex items-center gap-2 text-sm text-primary mb-4">
            <CheckCircle2 size={15} />
            Confirmed {lastResult.confirmed} attribution{lastResult.confirmed !== 1 ? "s" : ""}.
          </div>
        )}

        {error && (
          <p className="text-sm text-destructive mb-4">{error}</p>
        )}

        <Button
          onClick={runClearance}
          disabled={clearing || loading}
          className="flex items-center gap-2"
        >
          <Play size={14} />
          {clearing ? "Running…" : "Run Clearance"}
        </Button>
      </div>

      {/* Commission tiers info */}
      <div className="rounded-xl border border-border p-6 mt-6">
        <p className="text-sm font-semibold text-foreground mb-3">Affiliate Tier Rates</p>
        <table className="w-full text-sm">
          <thead>
            <tr className="text-xs uppercase tracking-wide text-muted-foreground border-b border-border">
              <th className="text-left pb-2">Tier</th>
              <th className="text-left pb-2">Rolling 30-day confirmed</th>
              <th className="text-right pb-2">Rate</th>
            </tr>
          </thead>
          <tbody className="text-foreground">
            {[
              { tier: "Bronze", range: "0 – 3", rate: "3%" },
              { tier: "Silver", range: "4 – 7", rate: "4%" },
              { tier: "Gold",   range: "8+",    rate: "5%" },
            ].map((row) => (
              <tr key={row.tier} className="border-b border-border last:border-0">
                <td className="py-2 font-medium">{row.tier}</td>
                <td className="py-2 text-muted-foreground">{row.range}</td>
                <td className="py-2 text-right font-[family-name:var(--font-mono)]">{row.rate}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { apiFail, apiOk, parseBody } from '@/lib/validation/schemas';
import { contentReviewSchema } from '@/lib/validation/vendor-schemas';
import { createClient } from '@/lib/supabase/server';
import { createServiceClient } from '@/lib/supabase/service';
import { auditAndNotify } from '@/lib/audit';

function relation(value: unknown) { return Array.isArray(value) ? value[0] : value; }

async function requireAdmin() {
  const db = await createClient();
  const { data: { user } } = await db.auth.getUser();
  if (!user) return { error: apiFail('UNAUTHORIZED', 'Sign in required', 401) } as const;
  const { data: roles, error } = await db.from('user_roles').select('roles(name)').eq('user_id', user.id);
  if (error) return { error: apiFail('DB_ERROR', error.message, 500) } as const;
  const names = (roles ?? []).map((row: any) => relation(row.roles)?.name);
  if (!names.some((name: string) => ['super_admin', 'approver'].includes(name))) {
    return { error: apiFail('FORBIDDEN', 'Administrator access required', 403) } as const;
  }
  return { db: createServiceClient(), user } as const;
}

export async function GET() {
  const auth = await requireAdmin();
  if ('error' in auth) return auth.error;
  const { db } = auth;
  const [outlets, products, vouchers] = await Promise.all([
    db.from('outlets').select('id,display_id,name,city,state,review_status,review_note,created_at,vendor_id,vendors(name)').eq('review_status', 'pending_review').order('created_at', { ascending: false }),
    db.from('products').select('id,display_id,name,product_type,base_price,review_status,review_note,created_at,vendor_id,vendors(name),outlets(name,city)').eq('review_status', 'pending_review').order('created_at', { ascending: false }),
    db.from('vouchers').select('id,code,name,discount_value,voucher_type,review_status,review_note,created_at,vendor_id,vendors(name),outlets(name,city)').eq('review_status', 'pending_review').order('created_at', { ascending: false }),
  ]);
  const failed = [outlets, products, vouchers].find((result) => result.error);
  if (failed?.error) return apiFail('DB_ERROR', failed.error.message, 500);
  return apiOk({
    items: [
      ...(outlets.data ?? []).map((item: any) => ({ ...item, entityType: 'outlet', entityLabel: item.name, context: [item.city, item.state].filter(Boolean).join(', ') })),
      ...(products.data ?? []).map((item: any) => ({ ...item, entityType: 'product', entityLabel: item.name, context: item.outlets?.city || item.outlets?.name || item.product_type })),
      ...(vouchers.data ?? []).map((item: any) => ({ ...item, entityType: 'voucher', entityLabel: `${item.code} · ${item.name}`, context: item.outlets?.city || 'All outlets' })),
    ].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()),
  });
}

export async function POST(request: Request) {
  const auth = await requireAdmin();
  if ('error' in auth) return auth.error;
  const { db, user } = auth;
  const parsed = await parseBody(request, contentReviewSchema);
  if (!parsed.ok) return parsed.response;
  const { entityType, entityId, action, note } = parsed.data;
  const table = entityType === 'outlet' ? 'outlets' : entityType === 'product' ? 'products' : 'vouchers';
  const { data: entity, error: entityError } = await db.from(table).select('*').eq('id', entityId).single();
  if (entityError || !entity) return apiFail('NOT_FOUND', 'Review item not found', 404);
  if (entity.review_status !== 'pending_review') return apiFail('INVALID_STATE', 'This item is no longer waiting for review', 409);

  const reviewStatus = action === 'approve' ? 'approved' : action;
  const update = entityType === 'voucher'
    ? { review_status: reviewStatus, review_note: note ?? null, reviewed_by: user.id, reviewed_at: new Date().toISOString(), is_active: action === 'approve' }
    : { review_status: reviewStatus, review_note: note ?? null, reviewed_by: user.id, reviewed_at: new Date().toISOString(), status: action === 'approve' ? 'active' : 'inactive' };
  const { data: updated, error: updateError } = await db.from(table).update(update).eq('id', entityId).select().single();
  if (updateError) return apiFail('DB_ERROR', updateError.message, 500);

  await db.from('content_reviews').insert({ entity_type: entityType, entity_id: entityId, vendor_id: entity.vendor_id, reviewer_id: user.id, action, note: note ?? null });
  await auditAndNotify({ action: `content.${action}`, entityType, entityId, beforeData: { review_status: entity.review_status }, afterData: { review_status: reviewStatus }, note });
  return apiOk(updated);
}

// P2 — Member 2 owns B1: Admin approve/reject vendor
// Uses auditAndNotify() (Gate 5) for every state change

import { createClient } from '@/lib/supabase/server';
import { auditAndNotify } from '@/lib/audit';
import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { vendorApproveSchema } from '@/lib/validation/vendor-schemas';

interface Props { params: Promise<{ id: string }> }

export async function POST(request: Request, { params }: Props) {
  const { id: vendorId } = await params;
  const supabase = await createClient();

  // Auth check
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return apiFail('UNAUTHORIZED', 'Sign in required', 401);

  // Role check — only super_admin or approver
  const { data: roles } = await supabase
    .from('user_roles')
    .select('roles(name)')
    .eq('user_id', user.id);

  const roleNames = (roles ?? []).map((r: any) => (r.roles as Record<string, any>)?.name as string);
  if (!roleNames.includes('super_admin') && !roleNames.includes('approver')) {
    return apiFail('FORBIDDEN', 'Only admin or approver can review vendors', 403);
  }

  // Parse body
  const parsed = await parseBody(request, vendorApproveSchema);
  if (!parsed.ok) return parsed.response;
  const { action, reason } = parsed.data;

  // Fetch current vendor
  const { data: vendor, error: fetchErr } = await supabase
    .from('vendors')
    .select('*')
    .eq('id', vendorId)
    .single();

  if (fetchErr || !vendor) return apiFail('NOT_FOUND', 'Vendor not found', 404);
  if (vendor.status !== 'pending') {
    return apiFail('INVALID_STATE', `Vendor is already ${vendor.status}`, 400);
  }

  if (action === 'approve') {
    // Update vendor status
    const { error: updateErr } = await supabase
      .from('vendors')
      .update({
        status: 'approved',
        approved_by: user.id,
        approved_at: new Date().toISOString(),
      })
      .eq('id', vendorId);

    if (updateErr) return apiFail('DB_ERROR', updateErr.message, 500);

    // Auto-create vendor_owner role for the vendor's owner
    const { data: ownerRole } = await supabase
      .from('roles')
      .select('id')
      .eq('name', 'vendor_owner')
      .single();

    if (ownerRole) {
      await supabase.from('user_roles').upsert({
        user_id: vendor.owner_id,
        role_id: ownerRole.id,
        vendor_id: vendorId,
      }, { onConflict: 'user_id,role_id,vendor_id,outlet_id' });
    }

    // Audit + notify vendor owner
    await auditAndNotify(
      {
        action: 'vendor.approved',
        entityType: 'vendor',
        entityId: vendorId,
        beforeData: { status: 'pending' },
        afterData: { status: 'approved' },
      },
      [{
        userId: vendor.owner_id,
        type: 'vendor_approved',
        title: `Your vendor "${vendor.name}" has been approved!`,
        body: 'You can now manage your outlets and products.',
        link: '/vendor/dashboard',
      }],
    );

    return apiOk({ id: vendorId, status: 'approved' });
  } else {
    // Reject
    const { error: updateErr } = await supabase
      .from('vendors')
      .update({
        status: 'rejected',
        rejection_reason: reason ?? null,
      })
      .eq('id', vendorId);

    if (updateErr) return apiFail('DB_ERROR', updateErr.message, 500);

    await auditAndNotify(
      {
        action: 'vendor.rejected',
        entityType: 'vendor',
        entityId: vendorId,
        beforeData: { status: 'pending' },
        afterData: { status: 'rejected', rejection_reason: reason },
        note: reason,
      },
      [{
        userId: vendor.owner_id,
        type: 'vendor_rejected',
        title: `Your vendor "${vendor.name}" was rejected`,
        body: reason ?? 'No reason provided.',
        link: '/vendor/dashboard',
      }],
    );

    return apiOk({ id: vendorId, status: 'rejected' });
  }
}

// P2 — Member 2 owns B1: Admin suspend/unsuspend vendor

import { createClient } from '@/lib/supabase/server';
import { auditAndNotify } from '@/lib/audit';
import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { vendorSuspendSchema } from '@/lib/validation/vendor-schemas';

interface Props { params: Promise<{ id: string }> }

export async function POST(request: Request, { params }: Props) {
  const { id: vendorId } = await params;
  const supabase = await createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return apiFail('UNAUTHORIZED', 'Sign in required', 401);

  // Role check
  const { data: roles } = await supabase
    .from('user_roles')
    .select('roles(name)')
    .eq('user_id', user.id);

  const roleNames = (roles ?? []).map((r: any) => (r.roles as Record<string, any>)?.name as string);
  if (!roleNames.includes('super_admin')) {
    return apiFail('FORBIDDEN', 'Only super admin can suspend vendors', 403);
  }

  const parsed = await parseBody(request, vendorSuspendSchema);
  if (!parsed.ok) return parsed.response;
  const { action, reason } = parsed.data;

  const { data: vendor } = await supabase
    .from('vendors')
    .select('*')
    .eq('id', vendorId)
    .single();

  if (!vendor) return apiFail('NOT_FOUND', 'Vendor not found', 404);

  if (action === 'suspend' && vendor.status !== 'approved') {
    return apiFail('INVALID_STATE', 'Only approved vendors can be suspended', 400);
  }
  if (action === 'unsuspend' && vendor.status !== 'suspended') {
    return apiFail('INVALID_STATE', 'Only suspended vendors can be unsuspended', 400);
  }

  const newStatus = action === 'suspend' ? 'suspended' : 'approved';

  const { error } = await supabase
    .from('vendors')
    .update({ status: newStatus })
    .eq('id', vendorId);

  if (error) return apiFail('DB_ERROR', error.message, 500);

  await auditAndNotify(
    {
      action: `vendor.${action}ed`,
      entityType: 'vendor',
      entityId: vendorId,
      beforeData: { status: vendor.status },
      afterData: { status: newStatus },
      note: reason,
    },
    [{
      userId: vendor.owner_id,
      type: `vendor_${action}ed`,
      title: action === 'suspend'
        ? `Your vendor "${vendor.name}" has been suspended`
        : `Your vendor "${vendor.name}" has been reactivated`,
      body: reason ?? undefined,
      link: '/vendor/dashboard',
    }],
  );

  return apiOk({ id: vendorId, status: newStatus });
}

import { NextResponse } from 'next/server';
import { createServiceClient } from '@/lib/supabase/service';
import { pickDemoAssignment, pickDemoRole } from '@/lib/auth/demo-user-role';
import type { Role, User } from '@/backend/core/types';

export const dynamic = 'force-dynamic';

type DemoUserRow = {
  id: string;
  email: string;
  full_name: string | null;
  city: string | null;
  tier: User['verificationTier'];
  user_roles?: Array<{
    vendor_id: string | null;
    outlet_id: string | null;
    roles?: { name: Role } | { name: Role }[] | null;
    vendors?: { name: string } | { name: string }[] | null;
    outlets?: { name: string } | { name: string }[] | null;
  }>;
};

/**
 * Demo-only account picker. This route intentionally returns only the
 * seeded demo identity/role projection; the service key stays server-side.
 * The anon role can enumerate users but cannot read user_roles after RLS is
 * enabled, which would make every account appear to be a customer.
 */
export async function GET() {
  try {
    const db = createServiceClient();
    const { data, error } = await db
      .from('users')
      .select('id,email,full_name,city,tier,user_roles(vendor_id,outlet_id,roles(name),vendors(name),outlets(name))')
      .like('email', '%@demo.local')
      .order('email');

    if (error) throw error;

    const users = ((data || []) as DemoUserRow[]).map((row) => {
      const assignments = row.user_roles || [];
      const role = pickDemoRole(assignments);
      const assignment = pickDemoAssignment(assignments);
      const assignmentRole = Array.isArray(assignment?.roles) ? assignment.roles[0] : assignment?.roles;
      const name = row.full_name || row.email;
      const vendor = Array.isArray(assignment?.vendors) ? assignment?.vendors[0] : assignment?.vendors;
      const outlet = Array.isArray(assignment?.outlets) ? assignment?.outlets[0] : assignment?.outlets;
      return {
        id: row.id,
        name,
        email: row.email,
        role,
        avatarInitial: name[0]?.toUpperCase() || '?',
        city: row.city || undefined,
        verificationTier: row.tier,
        vendorId: assignment?.vendor_id || undefined,
        outletId: assignment?.outlet_id || undefined,
        vendorName: vendor?.name || undefined,
        outletName: outlet?.name || undefined,
      };
    });

    return NextResponse.json(users);
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Unable to load demo accounts' },
      { status: 500 },
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import type { AuthUser } from '@/types';
import type { RoleName } from '@/lib/constants';

export const dynamic = 'force-dynamic';

type RoleRow = {
  vendor_id: string | null;
  outlet_id: string | null;
  roles?: { name: RoleName } | { name: RoleName }[] | null;
  outlets?: { vendor_id: string | null; name?: string | null } | { vendor_id: string | null; name?: string | null }[] | null;
};

type ManagerAssignmentRow = {
  outlet_id: string;
  outlets?: { vendor_id: string | null; name?: string | null } | { vendor_id: string | null; name?: string | null }[] | null;
};

type ProfileRow = {
  id: string;
  email: string | null;
  full_name: string | null;
  avatar_url: string | null;
  kyc_status: string | null;
  tier: string | null;
  email_verified_at: string | null;
  phone_verified_at: string | null;
  profile_completed_at: string | null;
};

export async function GET() {
  const supabase = await createClient();
  const { data: { user: authUser } } = await supabase.auth.getUser();
  if (!authUser) return NextResponse.json({ error: 'Sign in required' }, { status: 401 });

  const [{ data: profile, error: profileError }, { data: roleRows, error: rolesError }, { data: managerRows, error: managerError }] = await Promise.all([
    supabase.from('users').select('id,email,full_name,avatar_url,kyc_status,tier,email_verified_at,phone_verified_at,profile_completed_at').eq('id', authUser.id).maybeSingle(),
    supabase.from('user_roles').select('vendor_id,outlet_id,roles(name),outlets(vendor_id,name)').eq('user_id', authUser.id),
    supabase.from('outlet_managers').select('outlet_id,outlets(vendor_id,name)').eq('user_id', authUser.id),
  ]);
  if (profileError) return NextResponse.json({ error: profileError.message }, { status: 500 });
  if (rolesError) return NextResponse.json({ error: rolesError.message }, { status: 500 });
  if (managerError) return NextResponse.json({ error: managerError.message }, { status: 500 });

  const profileRow = profile as ProfileRow | null;
  const rows = (roleRows || []) as RoleRow[];
  const roles = rows.map((row) => {
    const role = Array.isArray(row.roles) ? row.roles[0] : row.roles;
    return role?.name;
  }).filter((role): role is RoleName => Boolean(role));
  const managerAssignments = (managerRows || []) as ManagerAssignmentRow[];
  const vendorIds = [...new Set([
    ...rows.flatMap((row) => {
      const outlet = Array.isArray(row.outlets) ? row.outlets[0] : row.outlets;
      return [row.vendor_id, outlet?.vendor_id];
    }),
    ...managerAssignments.map((row) => {
      const outlet = Array.isArray(row.outlets) ? row.outlets[0] : row.outlets;
      return outlet?.vendor_id;
    }),
  ].filter((id): id is string => Boolean(id)))];
  const outletIds = [...new Set(managerAssignments.map((row) => row.outlet_id))];
  const assignedOutletRelation = managerAssignments[0] ? (Array.isArray(managerAssignments[0].outlets) ? managerAssignments[0].outlets[0] : managerAssignments[0].outlets) : null;

  return NextResponse.json({
    user: {
      id: authUser.id,
      email: authUser.email || profileRow?.email || '',
      fullName: profileRow?.full_name || null,
      avatarUrl: profileRow?.avatar_url || null,
      kycStatus: profileRow?.kyc_status || 'unverified',
      tier: profileRow?.tier || 'email_verified',
      emailVerified: Boolean(profileRow?.email_verified_at),
      phoneVerified: Boolean(profileRow?.phone_verified_at),
      profileComplete: Boolean(profileRow?.profile_completed_at),
      roles,
      activeVendorId: vendorIds[0] || null,
      activeOutletIds: outletIds,
      activeOutletName: assignedOutletRelation?.name || null,
    },
  });
}

import { apiFail, apiOk, parseBody } from '@/lib/validation/schemas';
import { vendorBatchSchema, type VendorBatch } from '@/lib/validation/vendor-schemas';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

function safe(value: string | undefined) {
  return (value || '').trim().replace(/[%(),]/g, ' ');
}

function relation(value: any) {
  return Array.isArray(value) ? value[0] : value;
}

function voucherStatus(voucher: any) {
  const now = Date.now();
  const validFrom = voucher.valid_from ? new Date(voucher.valid_from).getTime() : null;
  const validUntil = voucher.valid_until ? new Date(voucher.valid_until).getTime() : null;
  if (!voucher.is_active) return 'inactive';
  if (validFrom && validFrom > now) return 'scheduled';
  if (validUntil && validUntil < now) return 'expired';
  if (voucher.max_uses && voucher.uses_count >= voucher.max_uses) return 'expired';
  return 'active';
}

async function findFilteredIds(db: any, vendorId: string, input: VendorBatch, scopedOutletIds?: string[]) {
  const filters = input.filters || {};
  const q = safe(filters.q as string | undefined);

  if (input.entity === 'products') {
    let query = db.from('products').select('id,name,slug').eq('vendor_id', vendorId);
    if (scopedOutletIds) query = query.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    if (filters.productType) query = query.eq('product_type', filters.productType);
    if (filters.status) query = query.eq('status', filters.status);
    if (filters.outletId) query = query.eq('outlet_id', filters.outletId);
    if (q) query = query.or('name.ilike.%' + q + '%,slug.ilike.%' + q + '%');
    const { data, error } = await query;
    if (error) throw error;
    return (data || []).map((item: any) => item.id);
  }

  if (input.entity === 'outlets') {
    let query = db.from('outlets').select('id,name,city').eq('vendor_id', vendorId);
    if (scopedOutletIds) query = query.in('id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    if (filters.state) query = query.eq('state', filters.state);
    if (filters.status) query = query.eq('status', filters.status);
    if (q) query = query.or('name.ilike.%' + q + '%,city.ilike.%' + q + '%');
    const { data, error } = await query;
    if (error) throw error;
    return (data || []).map((item: any) => item.id);
  }

  if (input.entity === 'vouchers') {
    let query = db.from('vouchers').select('id,code,name,is_active,valid_from,valid_until,max_uses,uses_count').eq('vendor_id', vendorId);
    if (q) query = query.or('code.ilike.%' + q + '%,name.ilike.%' + q + '%');
    const { data, error } = await query;
    if (error) throw error;
    return (data || []).filter((item: any) => !filters.status || voucherStatus(item) === filters.status).map((item: any) => item.id);
  }

  if (input.entity === 'slots') {
    const outletIds = scopedOutletIds ?? ((await db.from('outlets').select('id').eq('vendor_id', vendorId)).data || []).map((item: any) => item.id);
    let query = db.from('booking_slots').select('id,product_id,outlet_id,starts_at,status,products(name),outlets(name,city)').in('outlet_id', outletIds.length ? outletIds : ['none']);
    if (filters.status) query = query.eq('status', filters.status);
    if (filters.outletId) query = query.eq('outlet_id', filters.outletId);
    if (filters.productId) query = query.eq('product_id', filters.productId);
    if (filters.from) query = query.gte('starts_at', filters.from);
    if (filters.to) query = query.lte('starts_at', filters.to + 'T23:59:59.999Z');
    const { data, error } = await query;
    if (error) throw error;
    const searchTerm = q.toLowerCase();
    return (data || []).filter((item: any) => !searchTerm || [item.id, item.products?.name, item.outlets?.name, item.outlets?.city].some((value) => String(value || '').toLowerCase().includes(searchTerm))).map((item: any) => item.id);
  }

  if (input.entity === 'orders') {
    let orderQuery = db.from('order_items').select('id,order_id,product_name,variant_name,fulfil_status,created_at,outlet_id,orders!inner(status,users(full_name,email))').eq('vendor_id', vendorId);
    if (scopedOutletIds) orderQuery = orderQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    const { data, error } = await orderQuery;
    if (error) throw error;
    const searchTerm = ((filters.q as string) || '').toLowerCase().replace(/^#/, '');
    return (data || []).filter((item: any) => {
      const order = relation(item.orders);
      const customer = relation(order?.users);
      const matchesQ = !searchTerm || [item.id, item.order_id, item.product_name, item.variant_name, customer?.full_name, customer?.email].some((value) => String(value || '').toLowerCase().includes(searchTerm));
      const matchesFulfil = !filters.fulfilStatus || item.fulfil_status === filters.fulfilStatus;
      const matchesOrder = !filters.orderStatus || order?.status === filters.orderStatus;
      const created = item.created_at ? new Date(item.created_at).getTime() : 0;
      const from = filters.from ? new Date(filters.from as string).getTime() : null;
      const to = filters.to ? new Date((filters.to as string) + 'T23:59:59.999Z').getTime() : null;
      return matchesQ && matchesFulfil && matchesOrder && (!from || created >= from) && (!to || created <= to);
    }).map((item: any) => item.id);
  }

  const outletIds = scopedOutletIds ?? ((await db.from('outlets').select('id').eq('vendor_id', vendorId)).data || []).map((item: any) => item.id);
  if (!outletIds.length) return [];
  const { data: slots, error: slotError } = await db.from('booking_slots').select('id,starts_at').in('outlet_id', outletIds);
  if (slotError) throw slotError;
  const slotIds = (slots || []).map((item: any) => item.id);
  if (!slotIds.length) return [];
  let query = db.from('bookings').select('id,status,customer_id,users(full_name,email),order_items(product_name),booking_slots(starts_at)').in('slot_id', slotIds);
  if (filters.status) query = query.eq('status', filters.status);
  const { data, error } = await query;
  if (error) throw error;
  const searchTerm = ((filters.q as string) || '').toLowerCase().replace(/^#/, '');
  const from = filters.from ? new Date(filters.from as string).getTime() : null;
  const to = filters.to ? new Date((filters.to as string) + 'T23:59:59.999Z').getTime() : null;
  return (data || []).filter((item: any) => {
    const customer = relation(item.users);
    const orderItem = relation(item.order_items);
    const slot = relation(item.booking_slots);
    const starts = slot?.starts_at ? new Date(slot.starts_at).getTime() : 0;
    const matchesQ = !searchTerm || [item.id, customer?.full_name, customer?.email, orderItem?.product_name].some((value) => String(value || '').toLowerCase().includes(searchTerm));
    return matchesQ && (!from || starts >= from) && (!to || starts <= to);
  }).map((item: any) => item.id);
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;

  const parsed = await parseBody(request, vendorBatchSchema);
  if (!parsed.ok) return parsed.response;
  const input = parsed.data;
  if (access.access.isOutletManager && !['products', 'orders', 'bookings', 'slots'].includes(input.entity)) {
    return apiFail('FORBIDDEN', 'Outlet Managers can only batch-update products, bookings, orders, and availability', 403);
  }
  const db = access.access.serviceDb;
  const scopedOutletIds = access.access.isOutletManager ? access.access.outletIds : undefined;
  let scopedSlotIds: string[] | undefined;
  if (scopedOutletIds) {
    const { data: slots, error } = await db.from('booking_slots').select('id').in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    if (error) return apiFail('DB_ERROR', error.message, 500);
    scopedSlotIds = (slots || []).map((item: any) => item.id);
  }
  let targetIds = input.selectAllFiltered ? await findFilteredIds(db, vendorId, input, scopedOutletIds) : input.ids;
  targetIds = [...new Set(targetIds)];
  if (!targetIds.length) return apiOk({ entity: input.entity, action: input.action, requested: 0, updated: 0, skipped: 0 });

  let updatedIds: string[] = [];
  let skippedIds: string[] = [];

  if (input.entity === 'products') {
    const status = input.action === 'archive' ? 'archived' : input.action === 'restore' ? 'active' : null;
    if (!status) return apiFail('INVALID_ACTION', 'Products support archive or restore only', 400);
    let updateQuery = db.from('products').update({ status }).eq('vendor_id', vendorId).in('id', targetIds);
    if (scopedOutletIds) updateQuery = updateQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    const { data, error } = await updateQuery.select('id');
    if (error) return apiFail('DB_ERROR', error.message, 500);
    updatedIds = (data || []).map((item: any) => item.id);
  } else if (input.entity === 'outlets') {
    const status = input.action === 'close' ? 'closed' : input.action === 'activate' ? 'active' : null;
    if (!status) return apiFail('INVALID_ACTION', 'Outlets support close or activate only', 400);
    const { data, error } = await db.from('outlets').update({ status }).eq('vendor_id', vendorId).in('id', targetIds).select('id');
    if (error) return apiFail('DB_ERROR', error.message, 500);
    updatedIds = (data || []).map((item: any) => item.id);
  } else if (input.entity === 'vouchers') {
    const isActive = input.action === 'activate' ? true : input.action === 'deactivate' ? false : null;
    if (isActive === null) return apiFail('INVALID_ACTION', 'Vouchers support activate or deactivate only', 400);
    const { data, error } = await db.from('vouchers').update({ is_active: isActive }).eq('vendor_id', vendorId).in('id', targetIds).select('id');
    if (error) return apiFail('DB_ERROR', error.message, 500);
    updatedIds = (data || []).map((item: any) => item.id);
  } else if (input.entity === 'orders') {
    if (!['ready', 'fulfilled'].includes(input.action)) return apiFail('INVALID_ACTION', 'Orders support ready or fulfilled only', 400);
    let itemQuery = db.from('order_items').select('id,order_id,fulfil_status,orders!inner(status)').eq('vendor_id', vendorId).in('id', targetIds);
    if (scopedOutletIds) itemQuery = itemQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    const { data: items, error } = await itemQuery;
    if (error) return apiFail('DB_ERROR', error.message, 500);
    const valid = (items || []).filter((item: any) => {
      const orderStatus = relation(item.orders)?.status;
      return ['paid', 'completed'].includes(orderStatus) && (input.action === 'ready' ? item.fulfil_status === 'pending' : ['pending', 'ready'].includes(item.fulfil_status));
    }).map((item: any) => item.id);
    skippedIds = targetIds.filter((id: string) => !valid.includes(id));
    const updateData: Record<string, unknown> = { fulfil_status: input.action };
    if (input.action === 'fulfilled') updateData.fulfilled_at = new Date().toISOString();
    if (valid.length) {
      let updateQuery = db.from('order_items').update(updateData).in('id', valid);
      if (scopedOutletIds) updateQuery = updateQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
      const { data, error: updateError } = await updateQuery.select('id');
      if (updateError) return apiFail('DB_ERROR', updateError.message, 500);
      updatedIds = (data || []).map((item: any) => item.id);
    }
  } else if (input.entity === 'bookings') {
    if (!['check_in', 'cancel'].includes(input.action)) return apiFail('INVALID_ACTION', 'Bookings support check-in or cancel only', 400);
    let bookingQuery = db.from('bookings').select('id,status,order_item_id,slot_id').in('id', targetIds);
    if (scopedSlotIds) bookingQuery = bookingQuery.in('slot_id', scopedSlotIds.length ? scopedSlotIds : ['none']);
    const { data: bookings, error } = await bookingQuery;
    if (error) return apiFail('DB_ERROR', error.message, 500);
    const valid = (bookings || []).filter((item: any) => input.action === 'check_in' ? item.status === 'confirmed' : item.status === 'confirmed').map((item: any) => item.id);
    skippedIds = targetIds.filter((id: string) => !valid.includes(id));
    if (valid.length) {
      const updateData = input.action === 'check_in' ? { status: 'checked_in', check_in_at: new Date().toISOString() } : { status: 'cancelled', cancelled_at: new Date().toISOString() };
      let updateQuery = db.from('bookings').update(updateData).in('id', valid);
      if (scopedSlotIds) updateQuery = updateQuery.in('slot_id', scopedSlotIds.length ? scopedSlotIds : ['none']);
      const { data, error: updateError } = await updateQuery.select('id,order_item_id');
      if (updateError) return apiFail('DB_ERROR', updateError.message, 500);
      updatedIds = (data || []).map((item: any) => item.id);
      const orderItemIds = (data || []).map((item: any) => item.order_item_id).filter(Boolean);
      if (input.action === 'check_in' && orderItemIds.length) await db.from('order_items').update({ fulfil_status: 'fulfilled', fulfilled_at: new Date().toISOString() }).in('id', orderItemIds);
    }
  } else {
    if (!['cancel', 'restore'].includes(input.action)) return apiFail('INVALID_ACTION', 'Slots support cancel or restore only', 400);
    const targetStatus = input.action === 'cancel' ? 'cancelled' : 'available';
    const validStatuses = input.action === 'cancel' ? ['available', 'full'] : ['cancelled'];
    let slotQuery = db.from('booking_slots').select('id,status,booked').in('id', targetIds);
    if (scopedOutletIds) slotQuery = slotQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
    const { data: slots, error } = await slotQuery;
    if (error) return apiFail('DB_ERROR', error.message, 500);
    const valid = (slots || []).filter((item: any) => validStatuses.includes(item.status) && (input.action === 'cancel' ? true : item.booked === 0)).map((item: any) => item.id);
    skippedIds = targetIds.filter((id: string) => !valid.includes(id));
    if (valid.length) {
      let updateQuery = db.from('booking_slots').update({ status: targetStatus }).in('id', valid);
      if (scopedOutletIds) updateQuery = updateQuery.in('outlet_id', scopedOutletIds.length ? scopedOutletIds : ['none']);
      const { data, error: updateError } = await updateQuery.select('id');
      if (updateError) return apiFail('DB_ERROR', updateError.message, 500);
      updatedIds = (data || []).map((item: any) => item.id);
    }
  }

  return apiOk({ entity: input.entity, action: input.action, requested: targetIds.length, updated: updatedIds.length, skipped: skippedIds.length, skippedIds });
}

import { createClient } from '@/lib/supabase/server';
import { createServiceClient } from '@/lib/supabase/service';
import { apiFail, apiOk } from '@/lib/validation/schemas';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const service = access.access.serviceDb;
  const url = new URL(request.url);
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(50, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const rawQ = (url.searchParams.get('q') || '').trim().replace(/^#/, '');
  const q = rawQ.replace(/[%(),]/g, ' ');
  const status = url.searchParams.get('status');
  const from = url.searchParams.get('from');
  const to = url.searchParams.get('to');
  const outletId = url.searchParams.get('outletId');
  const productId = url.searchParams.get('productId');
  const vendorOutletIds = access.access.outletIds;
  const outletIds = outletId && vendorOutletIds.includes(outletId) ? [outletId] : vendorOutletIds;
  if (!outletIds.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 }, stats: {} });
  let slotQuery = service.from('booking_slots').select('id').in('outlet_id', outletIds);
  if (productId) slotQuery = slotQuery.eq('product_id', productId);
  if (from) slotQuery = slotQuery.gte('starts_at', from);
  if (to) slotQuery = slotQuery.lte('starts_at', to);
  const { data: slots, error: slotError } = await slotQuery;
  if (slotError) return apiFail('DB_ERROR', slotError.message, 500);
  const slotIds = (slots || []).map((slot: any) => slot.id);
  if (!slotIds.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 }, stats: {} });

  let query = service.from('bookings').select('id,display_id,status,created_at,check_in_at,demo_qr_code,customer_id,slot_id,order_item_id,order_items!inner(product_name,quantity,line_total,slot_starts_at,product_id,outlet_id,products(name,cover_url),outlets(id,name,city,state)),users(full_name,email),booking_slots!inner(starts_at,ends_at,capacity,booked,products(name,cover_url),outlets(id,name,city,state))', { count: 'exact' }).in('slot_id', slotIds);
  if (status && status !== 'all') query = query.eq('status', status);

  if (q) {
    const [{ data: matchingUsers }, { data: matchingItems }, { data: bookingIds }] = await Promise.all([
      service.from('users').select('id').or(`full_name.ilike.%${q}%,email.ilike.%${q}%`).limit(100),
      service.from('order_items').select('id').eq('vendor_id', vendorId).in('outlet_id', vendorOutletIds).ilike('product_name', `%${q}%`).limit(100),
      service.from('bookings').select('id').in('slot_id', slotIds).ilike('display_id', `%${q}%`).limit(100),
    ]);
    const userIds = (matchingUsers || []).map((item: any) => item.id);
    const itemIds = (matchingItems || []).map((item: any) => item.id);
    const matchingBookingIds = (bookingIds || []).map((item: any) => item.id);
    const conditions = [];
    if (userIds.length) conditions.push(`customer_id.in.(${userIds.join(',')})`);
    if (itemIds.length) conditions.push(`order_item_id.in.(${itemIds.join(',')})`);
    if (matchingBookingIds.length) conditions.push(`id.in.(${matchingBookingIds.join(',')})`);
    if (!conditions.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 }, stats: {} });
    query = query.or(conditions.join(','));
  }

  const { data, error, count } = await query.order('created_at', { ascending: false }).range((page - 1) * pageSize, page * pageSize - 1);
  if (error) return apiFail('DB_ERROR', error.message, 500);
  const { data: statRows } = await service.from('bookings').select('status').in('slot_id', slotIds);
  const stats = (statRows || []).reduce((result: Record<string, number>, item: any) => {
    result[item.status] = (result[item.status] || 0) + 1;
    return result;
  }, {});
  const items = (data || []).map((booking: any) => ({
    ...booking,
    customer: Array.isArray(booking.users) ? booking.users[0] : booking.users,
    orderItem: (() => { const item = Array.isArray(booking.order_items) ? booking.order_items[0] : booking.order_items; return item ? { ...item, outlets: item.outlets ? { ...item.outlets, full_name: item.outlets.name, name: outletShortName(item.outlets.name) } : item.outlets } : item; })(),
    slot: (() => { const slot = Array.isArray(booking.booking_slots) ? booking.booking_slots[0] : booking.booking_slots; return slot ? { ...slot, outlets: slot.outlets ? { ...slot.outlets, full_name: slot.outlets.name, name: outletShortName(slot.outlets.name) } : slot.outlets } : slot; })(),
  }));
  return apiOk({ items, pagination: { page, pageSize, total: count || 0, totalPages: Math.max(1, Math.ceil((count || 0) / pageSize)) }, stats });
}

import { apiFail, apiOk } from '@/lib/validation/schemas';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

async function authorize(vendorId: string) {
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return { error: access.response };
  return { user: { id: access.access.userId }, service: access.access.serviceDb, outletIds: access.access.outletIds };
}

export async function GET(_request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorize(vendorId);
  if ('error' in access) return access.error;
  const outletIds = access.outletIds;
  if (!outletIds.length) return apiOk([]);
  const { data, error } = await access.service.from('chat_threads').select('id,customer_id,outlet_id,status,last_message_at,created_at,customer:users!chat_threads_customer_id_fkey(full_name,email),outlets(id,name,city,state),chat_messages(id,sender_id,body,created_at)').in('outlet_id', outletIds).order('last_message_at', { ascending: false });
  if (error) return apiFail('DB_ERROR', error.message, 500);
  return apiOk((data || []).map((thread: any) => ({ ...thread, outlets: thread.outlets ? { ...thread.outlets, full_name: thread.outlets.name, name: outletShortName(thread.outlets.name) } : thread.outlets })));
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorize(vendorId);
  if ('error' in access) return access.error;
  let body: { threadId?: string; body?: string } = {};
  try { body = await request.json(); } catch { return apiFail('INVALID_BODY', 'Message body is required', 400); }
  if (!body.threadId || !body.body?.trim()) return apiFail('INVALID_BODY', 'Message body is required', 400);

  const { data: thread } = await access.service.from('chat_threads').select('id,outlet_id').eq('id', body.threadId).maybeSingle();
  if (!thread) return apiFail('NOT_FOUND', 'Conversation not found', 404);
  const { data: outlet } = await access.service.from('outlets').select('id').eq('id', thread.outlet_id).eq('vendor_id', vendorId).in('id', access.outletIds).maybeSingle();
  if (!outlet) return apiFail('FORBIDDEN', 'Conversation is outside this vendor', 403);

  const { data: message, error } = await access.service.from('chat_messages').insert({ thread_id: thread.id, sender_id: access.user.id, body: body.body.trim() }).select().single();
  if (error) return apiFail('DB_ERROR', error.message, 500);
  await access.service.from('chat_threads').update({ last_message_at: new Date().toISOString() }).eq('id', thread.id);
  return apiOk(message, { status: 201 });
}

// P2 — Member 2: Fulfil order item (B4)
// POST /api/vendors/[vendorId]/orders/[orderItemId]/fulfil
// Updates fulfil_status: pending → ready → fulfilled

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { fulfilSchema } from '@/lib/validation/vendor-schemas';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string; orderItemId: string }> }

export async function POST(request: Request, { params }: Props) {
  const { vendorId, orderItemId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;
  const outletIds = access.access.outletIds;

  const parsed = await parseBody(request, fulfilSchema);
  if (!parsed.ok) return parsed.response;
  const { status: newStatus } = parsed.data;
  // Get current order item
  const { data: item } = await supabase
    .from('order_items')
    .select('*, orders(status)')
    .eq('id', orderItemId)
    .in('outlet_id', outletIds)
    .single();

  if (!item) return apiFail('NOT_FOUND', 'Order item not found or not in your outlets', 404);

  // Validate state transition
  const order = item.orders as Record<string, unknown>;
  if (order?.status !== 'paid' && order?.status !== 'completed') {
    return apiFail('INVALID_STATE', 'Order must be paid before fulfilling items', 400);
  }

  if (newStatus === 'ready' && item.fulfil_status !== 'pending') {
    return apiFail('INVALID_STATE', `Cannot mark ready: current status is ${item.fulfil_status}`, 400);
  }
  if (newStatus === 'fulfilled' && item.fulfil_status !== 'pending' && item.fulfil_status !== 'ready') {
    return apiFail('INVALID_STATE', `Cannot fulfil: current status is ${item.fulfil_status}`, 400);
  }

  const updateData: Record<string, unknown> = { fulfil_status: newStatus };
  if (newStatus === 'fulfilled') {
    updateData.fulfilled_at = new Date().toISOString();
  }

  const { error } = await supabase
    .from('order_items')
    .update(updateData)
    .eq('id', orderItemId);

  if (error) return apiFail('DB_ERROR', error.message, 500);

  // Check if all items in this order are fulfilled — if so, suggest completing
  const { data: allItems } = await supabase
    .from('order_items')
    .select('fulfil_status')
    .eq('order_id', item.order_id);

  const allFulfilled = (allItems ?? []).every((i: any) => i.fulfil_status === 'fulfilled');

  return apiOk({
    id: orderItemId,
    fulfilStatus: newStatus,
    allItemsFulfilled: allFulfilled,
    orderId: item.order_id,
  });
}

// P2 — Member 2: Vendor order items view (B4)
// GET /api/vendors/[vendorId]/orders

import { createClient } from '@/lib/supabase/server';
import { apiOk, apiFail } from '@/lib/validation/schemas';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const authDb = await createClient() as any;
  const url = new URL(request.url);
  const fulfilStatus = url.searchParams.get('fulfil_status');
  const orderStatus = url.searchParams.get('order_status');
  const rawQ = (url.searchParams.get('q') || '').trim();
  const q = rawQ.replace(/[%(),]/g, ' ');
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(50, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const from = url.searchParams.get('from');
  const to = url.searchParams.get('to');

  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;

  const { createServiceClient } = await import('@/lib/supabase/service');
  const supabase = access.access.serviceDb;

  // Get vendor outlets
  const outletIds = access.access.outletIds;

  if (!outletIds.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 } });

  let query = supabase
    .from('orders')
    .select(`
      id, display_id, user_id, status, paid_at, completed_at, created_at,
      users(full_name, email),
      order_items!inner(
        id, order_id, product_name, variant_name, slot_starts_at, quantity, line_total, fulfil_status, created_at, vendor_id,
        outlets(id, name, city, state),
        products(cover_url)
      )
    `, { count: 'exact' })
    .eq('order_items.vendor_id', vendorId)
    .in('order_items.outlet_id', outletIds)
    .order('created_at', { ascending: false });

  if (fulfilStatus) query = query.eq('order_items.fulfil_status', fulfilStatus);
  if (orderStatus && orderStatus !== 'all') query = query.eq('status', orderStatus);
  if (q) {
    const [{ data: vendorItems }, { data: matchingUsers }, { data: matchingOrders }] = await Promise.all([
      supabase.from('order_items').select('id,order_id,product_name,variant_name').eq('vendor_id', vendorId).limit(10000),
      supabase.from('users').select('id').or(`full_name.ilike.%${q}%,email.ilike.%${q}%`).limit(100),
      supabase.from('orders').select('id').ilike('display_id', `%${q}%`).limit(100)
    ]);
    const searchTerm = rawQ.toLowerCase();
    const matchingOrderIds = [
      ...(vendorItems || []).filter((item: any) => String(item.product_name || '').toLowerCase().includes(searchTerm) || String(item.variant_name || '').toLowerCase().includes(searchTerm)).map((item: any) => item.order_id),
      ...(matchingOrders || []).map((item: any) => item.id)
    ];
    const userIds = (matchingUsers || []).map((item: any) => item.id);
    if (userIds.length) {
      const { data: userOrders } = await supabase.from('orders').select('id').in('user_id', userIds).limit(10000);
      matchingOrderIds.push(...(userOrders || []).map((item: any) => item.id));
    }
    const conditions = [];
    if (matchingOrderIds.length) conditions.push(`id.in.(${[...new Set(matchingOrderIds)].join(',')})`);
    if (!conditions.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 } });
    query = query.or(conditions.join(','));
  }
  if (from) query = query.gte('created_at', from);
  if (to) query = query.lte('created_at', to);

  const { data, error, count } = await query.range((page - 1) * pageSize, page * pageSize - 1);
  if (error) return apiFail('DB_ERROR', error.message, 500);

  const items = (data ?? []).map((order: any) => {
    // Ensure we only process this vendor's items
    const vendorItems = (order.order_items || []).filter((i: any) => i.vendor_id === vendorId);
    const total = vendorItems.reduce((sum: number, item: any) => sum + Number(item.line_total || 0), 0);
    const uniqueOutlets = [...new Set(vendorItems.map((item: any) => item.outlets?.name ? outletShortName(item.outlets.name) : null).filter(Boolean))];

    let fulfil_status = 'pending';
    if (vendorItems.length > 0) {
      if (vendorItems.every((item: any) => item.fulfil_status === 'fulfilled')) fulfil_status = 'fulfilled';
      else if (vendorItems.every((item: any) => item.fulfil_status === 'cancelled')) fulfil_status = 'cancelled';
      else if (vendorItems.every((item: any) => item.fulfil_status === 'ready' || item.fulfil_status === 'fulfilled')) fulfil_status = 'ready';
    }

    return {
      ...order,
      vendor_total: total,
      vendor_items: vendorItems,
      outlets_summary: uniqueOutlets.length > 1 ? 'Multiple outlets' : (uniqueOutlets[0] || 'Unknown outlet'),
      vendor_fulfil_status: fulfil_status,
      // Provide a product summary string
      product_summary: vendorItems.map((i: any) => `${i.quantity}x ${i.product_name}`).join(', ')
    };
  });

  return apiOk({ items, pagination: { page, pageSize, total: count || 0, totalPages: Math.max(1, Math.ceil((count || 0) / pageSize)) } });
}

import { z } from 'zod';
import { apiFail, apiOk, parseBody } from '@/lib/validation/schemas';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

const assignmentSchema = z.object({ outletId: z.string().uuid(), userId: z.string().uuid() }).strict();

export async function GET(_request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId, ['vendor_owner']);
  if (!access.ok) return access.response;
  const db = access.access.serviceDb;

  const { data: outlets, error: outletError } = await db.from('outlets').select('id,name,city,state').eq('vendor_id', vendorId).order('name');
  if (outletError) return apiFail('DB_ERROR', outletError.message, 500);
  const outletIds = (outlets || []).map((outlet: any) => outlet.id);

  const [{ data: assignments, error: assignmentError }, { data: role, error: roleError }] = await Promise.all([
    db.from('outlet_managers').select('outlet_id,user_id,users(id,full_name,email)').in('outlet_id', outletIds.length ? outletIds : ['none']),
    db.from('roles').select('id').eq('name', 'outlet_manager').maybeSingle(),
  ]);
  if (assignmentError || roleError) return apiFail('DB_ERROR', (assignmentError || roleError).message, 500);

  const { data: roleUsers, error: roleUsersError } = role
    ? await db.from('user_roles').select('user_id,users(id,full_name,email)').eq('role_id', role.id)
    : { data: [], error: null };
  if (roleUsersError) return apiFail('DB_ERROR', roleUsersError.message, 500);

  const normalizeUser = (value: any) => {
    const user = Array.isArray(value) ? value[0] : value;
    return user ? { id: user.id, fullName: user.full_name, email: user.email } : null;
  };
  const assignmentByOutlet = new Map((assignments || []).map((assignment: any) => [assignment.outlet_id, {
    userId: assignment.user_id,
    user: normalizeUser(assignment.users),
  }]));
  const eligibleManagers = [...new Map((roleUsers || []).map((row: any) => {
    const user = normalizeUser(row.users);
    return user ? [user.id, user] : null;
  }).filter(Boolean) as Array<[string, { id: string; fullName: string; email: string }]>).values()];

  return apiOk({
    outlets: (outlets || []).map((outlet: any) => ({ ...outlet, manager: assignmentByOutlet.get(outlet.id) || null })),
    eligibleManagers,
  });
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId, ['vendor_owner']);
  if (!access.ok) return access.response;
  const parsed = await parseBody(request, assignmentSchema);
  if (!parsed.ok) return parsed.response;
  const { outletId, userId } = parsed.data;
  const db = access.access.serviceDb;

  const [{ data: outlet }, { data: role }] = await Promise.all([
    db.from('outlets').select('id').eq('id', outletId).eq('vendor_id', vendorId).maybeSingle(),
    db.from('roles').select('id').eq('name', 'outlet_manager').maybeSingle(),
  ]);
  if (!outlet) return apiFail('INVALID_OUTLET', 'Outlet not found in this vendor', 400);
  if (!role) return apiFail('DB_ERROR', 'Outlet Manager role is not configured', 500);

  const [{ data: userRole }, { data: outletAssignment }, { data: userAssignment }] = await Promise.all([
    db.from('user_roles').select('user_id').eq('user_id', userId).eq('role_id', role.id).maybeSingle(),
    db.from('outlet_managers').select('user_id').eq('outlet_id', outletId).maybeSingle(),
    db.from('outlet_managers').select('outlet_id').eq('user_id', userId).maybeSingle(),
  ]);
  if (!userRole) return apiFail('FORBIDDEN', 'The selected account is not an Outlet Manager', 400);
  if (outletAssignment && outletAssignment.user_id !== userId) return apiFail('CONFLICT', 'This outlet already has an Outlet Manager', 409);
  if (userAssignment && userAssignment.outlet_id !== outletId) return apiFail('CONFLICT', 'This manager is already assigned to another outlet', 409);

  const { error: assignmentError } = await db.from('outlet_managers').upsert({ outlet_id: outletId, user_id: userId }, { onConflict: 'outlet_id' });
  if (assignmentError) return apiFail('DB_ERROR', assignmentError.message, 400);
  const { error: roleError } = await db.from('user_roles').upsert({ user_id: userId, role_id: role.id, vendor_id: vendorId, outlet_id: outletId }, { onConflict: 'user_id,role_id,vendor_id,outlet_id' });
  if (roleError) return apiFail('DB_ERROR', roleError.message, 400);
  return apiOk({ outletId, userId });
}

// P2 — Member 2: Outlet CRUD (B2)
// GET /api/vendors/[vendorId]/outlets — list outlets
// POST /api/vendors/[vendorId]/outlets — create outlet

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { outletCreateSchema } from '@/lib/validation/vendor-schemas';
import { slugify } from '@/lib/utils';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;
  const url = new URL(request.url);
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(24, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const q = url.searchParams.get('q')?.trim() || '';
  const state = url.searchParams.get('state');
  const status = url.searchParams.get('status');
  const sort = url.searchParams.get('sort') || 'newest';

  let query = supabase
    .from('outlets')
    .select('id,display_id,name,slug,address,city,state,postcode,country,lat,lng,phone,email,operating_hours,status,review_status,review_note,created_at,outlet_pages(hero_url,brand_colour),products(count),outlet_managers(user_id,users(id,full_name,email))', { count: 'exact' })
    .in('id', access.access.outletIds.length ? access.access.outletIds : ['none'])
    .range((page - 1) * pageSize, page * pageSize - 1);

  if (q) {
    const safeQ = q.replace(/[%(),]/g, ' ');
    query = query.or(`display_id.ilike.%${safeQ}%,name.ilike.%${safeQ}%,city.ilike.%${safeQ}%`);
  }
  if (state) query = query.eq('state', state);
  if (status) query = query.eq('status', status);
  query = query.order(sort === 'name' ? 'name' : 'created_at', { ascending: sort === 'name' });

  const [{ data, error, count }, { data: stateRows, error: stateError }] = await Promise.all([
    query,
    supabase.from('outlets').select('state').in('id', access.access.outletIds.length ? access.access.outletIds : ['none']).not('state', 'is', null).order('state'),
  ]);
  if (error || stateError) return apiFail('DB_ERROR', (error || stateError).message, 500);
  const items = (data ?? []).map((outlet: any) => {
    const outletPage = Array.isArray(outlet.outlet_pages) ? outlet.outlet_pages[0] : outlet.outlet_pages;
    const assignment = Array.isArray(outlet.outlet_managers) ? outlet.outlet_managers[0] : outlet.outlet_managers;
    const manager = Array.isArray(assignment?.users) ? assignment.users[0] : assignment?.users;
    return { ...outlet, coverUrl: outletPage?.hero_url || null, productsCount: outlet.products?.[0]?.count ?? 0, manager: manager ? { id: manager.id, fullName: manager.full_name, email: manager.email } : null };
  });
  return apiOk({ items, availableStates: [...new Set((stateRows || []).map((row: any) => row.state))], pagination: { page, pageSize, total: count || 0, totalPages: Math.max(1, Math.ceil((count || 0) / pageSize)) } });
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId, ['vendor_owner']);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;

  const { data: vendor } = await supabase
    .from('vendors')
    .select('id, owner_id, status')
    .eq('id', vendorId)
    .single();

  if (!vendor) return apiFail('NOT_FOUND', 'Vendor not found', 404);
  if (vendor.status !== 'approved') return apiFail('INVALID_STATE', 'Vendor not approved', 400);

  const parsed = await parseBody(request, outletCreateSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;

  const finalSlug = body.slug || slugify(`${body.name}-${body.city || 'outlet'}`);

  const { data, error } = await supabase.from('outlets').insert({
    vendor_id: vendorId,
    name: body.name,
    slug: finalSlug,
    address: body.address ?? null,
    city: body.city ?? null,
    state: body.state ?? null,
    postcode: body.postcode ?? null,
    country: body.country ?? 'Malaysia',
    lat: body.lat ?? null,
    lng: body.lng ?? null,
    phone: body.phone ?? null,
    email: body.email || null,
    operating_hours: body.operatingHours ?? null,
    status: 'inactive',
    review_status: 'pending_review',
  }).select().single();

  if (error) return apiFail('DB_ERROR', error.message, 400);
  return apiOk(data, { status: 201 });
}

// P2 — Single variant PATCH/DELETE with vendor + outlet scope enforcement.

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { variantUpdateSchema } from '@/lib/validation/vendor-schemas';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string; productId: string; variantId: string }> }

async function scopedProduct(serviceDb: any, vendorId: string, productId: string, outletIds: string[]) {
  const { data } = await serviceDb
    .from('products')
    .select('id,outlet_id,requires_booking,review_status')
    .eq('id', productId)
    .eq('vendor_id', vendorId)
    .in('outlet_id', outletIds)
    .maybeSingle();
  return data;
}

async function refreshStockStatus(serviceDb: any, vendorId: string, productId: string) {
  const { data: variants } = await serviceDb
    .from('product_variants')
    .select('id,is_active,inventory(quantity,reserved)')
    .eq('product_id', productId);
  const available = (variants || []).some((variant: any) => variant.is_active && Number(variant.inventory?.[0]?.quantity || 0) - Number(variant.inventory?.[0]?.reserved || 0) > 0);
  const { data: product } = await serviceDb.from('products').select('requires_booking,review_status').eq('id', productId).eq('vendor_id', vendorId).maybeSingle();
  if (!product?.requires_booking) {
    await serviceDb
      .from('products')
      .update({ status: available && product.review_status === 'approved' ? 'active' : 'inactive' })
      .eq('id', productId)
      .eq('vendor_id', vendorId);
  }
}

export async function PATCH(request: Request, { params }: Props) {
  const { vendorId, productId, variantId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const serviceDb = access.access.serviceDb;

  const product = await scopedProduct(serviceDb, vendorId, productId, access.access.outletIds);
  if (!product) return apiFail('NOT_FOUND', 'Product not found', 404);
  const { data: variant } = await serviceDb.from('product_variants').select('id').eq('id', variantId).eq('product_id', productId).maybeSingle();
  if (!variant) return apiFail('NOT_FOUND', 'Variant not found', 404);

  const parsed = await parseBody(request, variantUpdateSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;
  const variantUpdate: Record<string, unknown> = {};
  if (body.name !== undefined) variantUpdate.name = body.name;
  if (body.priceOffset !== undefined) variantUpdate.price_offset = body.priceOffset;
  if (body.sku !== undefined) variantUpdate.sku = body.sku;
  if (body.isActive !== undefined) variantUpdate.is_active = body.isActive;

  if (body.isDefault) {
    await serviceDb.from('product_variants').update({ is_default: false }).eq('product_id', productId);
    variantUpdate.is_default = true;
  }

  if (Object.keys(variantUpdate).length) {
    const { error } = await serviceDb.from('product_variants').update(variantUpdate).eq('id', variantId).eq('product_id', productId);
    if (error) return apiFail('DB_ERROR', error.message, 500);
  }

  if (body.quantity !== undefined) {
    const { error } = await serviceDb.from('inventory').upsert({ variant_id: variantId, quantity: body.quantity }, { onConflict: 'variant_id' });
    if (error) return apiFail('DB_ERROR', error.message, 500);
    await refreshStockStatus(serviceDb, vendorId, productId);
  }

  const { data: updated, error } = await serviceDb.from('product_variants').select('*, inventory(*)').eq('id', variantId).single();
  if (error) return apiFail('DB_ERROR', error.message, 500);
  return apiOk(updated);
}

export async function DELETE(_request: Request, { params }: Props) {
  const { vendorId, productId, variantId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const serviceDb = access.access.serviceDb;
  const product = await scopedProduct(serviceDb, vendorId, productId, access.access.outletIds);
  if (!product) return apiFail('NOT_FOUND', 'Product not found', 404);

  const { error } = await serviceDb.from('product_variants').update({ is_active: false }).eq('id', variantId).eq('product_id', productId);
  if (error) return apiFail('DB_ERROR', error.message, 500);
  await refreshStockStatus(serviceDb, vendorId, productId);
  return apiOk({ id: variantId, is_active: false });
}

// P2 — Member 2: Product CRUD (B2)
// GET /api/vendors/[vendorId]/products — list products
// POST /api/vendors/[vendorId]/products — create product + default variant

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { productCreateSchema } from '@/lib/validation/vendor-schemas';
import { slugify } from '@/lib/utils';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;
  const url = new URL(request.url);
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(24, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const outletId = url.searchParams.get('outlet_id');
  const categoryId = url.searchParams.get('category_id');
  const status = url.searchParams.get('status');
  const productType = url.searchParams.get('product_type');
  const q = url.searchParams.get('q')?.trim() || '';
  const sort = url.searchParams.get('sort') || 'newest';

  let query = supabase
    .from('products')
    .select('id,display_id,name,slug,description,product_type,requires_booking,base_price,cover_url,status,review_status,review_note,category_id,outlet_id,created_at,tags,default_capacity,digital_asset_url,digital_asset_name,digital_asset_type,digital_asset_size,media_assets(id,url,alt_text,sort_order),outlets(id,display_id,name,city,state),product_variants(id,name,price_offset,is_default,is_active,inventory(quantity,reserved,low_stock_threshold))', { count: 'exact' })
    .eq('vendor_id', vendorId)
    .in('outlet_id', access.access.outletIds.length ? access.access.outletIds : ['none'])
    .range((page - 1) * pageSize, page * pageSize - 1);

  if (outletId) query = query.eq('outlet_id', outletId);
  if (categoryId) query = query.eq('category_id', categoryId);
  if (status) query = query.eq('status', status);
  if (productType) query = query.eq('product_type', productType);
  if (q) {
    const safeQ = q.replace(/[%(),]/g, ' ');
    // We now have a true database display_id, so we can natively search it!
    query = query.or(`display_id.ilike.%${safeQ}%,name.ilike.%${safeQ}%,slug.ilike.%${safeQ}%`);
  }
  query = query.order(sort === 'name' ? 'name' : sort === 'price_low' ? 'base_price' : 'created_at', { ascending: sort === 'name' || sort === 'price_low' });

  const { data, error, count } = await query;
  if (error) return apiFail('DB_ERROR', error.message, 500);
  const items = (data ?? []).map((product: any) => ({
    ...product,
    outlet: product.outlets ? { ...product.outlets, full_name: product.outlets.name, name: outletShortName(product.outlets.name) } : product.outlets,
    variants: product.product_variants ?? [],
    availableStock: (product.product_variants ?? []).reduce((total: number, variant: any) => total + Math.max(0, Number(variant.inventory?.[0]?.quantity ?? 0) - Number(variant.inventory?.[0]?.reserved ?? 0)), 0),
    lowStockThreshold: (product.product_variants ?? []).reduce((threshold: number, variant: any) => Math.max(threshold, Number(variant.inventory?.[0]?.low_stock_threshold ?? 5)), 0),
  }));
  return apiOk({ items, pagination: { page, pageSize, total: count || 0, totalPages: Math.max(1, Math.ceil((count || 0) / pageSize)) } });
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;

  const { data: vendor } = await supabase
    .from('vendors')
    .select('id, owner_id, status')
    .eq('id', vendorId)
    .single();

  if (!vendor) return apiFail('NOT_FOUND', 'Vendor not found', 404);
  if (vendor.status !== 'approved') return apiFail('INVALID_STATE', 'Vendor not approved', 400);

  const parsed = await parseBody(request, productCreateSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;

  // Verify outlet belongs to vendor
  const { data: outlet } = await supabase
    .from('outlets')
    .select('id')
    .eq('id', body.outletId)
    .eq('vendor_id', vendorId)
    .single();
  if (!outlet) return apiFail('INVALID_OUTLET', 'Outlet not found or not owned by this vendor', 400);
  if (!access.access.outletIds.includes(body.outletId)) {
    return apiFail('FORBIDDEN', 'This outlet is outside your assigned scope', 403);
  }

  const finalSlug = body.slug || slugify(body.name);

  // Create product
  const { data: product, error: prodErr } = await supabase.from('products').insert({
    vendor_id: vendorId,
    outlet_id: body.outletId,
    category_id: body.categoryId ?? null,
    name: body.name,
    slug: finalSlug,
    description: body.description ?? null,
    product_type: body.productType,
    requires_booking: body.requiresBooking,
    base_price: body.basePrice,
    cover_url: body.coverUrl || null,
    tags: body.tags ?? null,
    status: 'inactive',
    review_status: body.submissionMode === 'draft' ? 'draft' : 'pending_review',
    default_capacity: body.defaultCapacity ?? null,
    digital_asset_url: body.digitalAssetUrl || null,
    digital_asset_name: body.digitalAssetName || null,
    digital_asset_type: body.digitalAssetType || null,
    digital_asset_size: body.digitalAssetSize ?? null,
  }).select().single();

  if (prodErr) return apiFail('DB_ERROR', prodErr.message, 400);

  if (body.gallery?.length) {
    const { error: mediaError } = await supabase.from('media_assets').insert(body.gallery.map((media, index) => ({
      vendor_id: vendorId,
      outlet_id: body.outletId,
      product_id: product!.id,
      url: media.url,
      alt_text: media.alt || body.name,
      media_type: 'image',
      sort_order: index,
    })));
    if (mediaError) return apiFail('DB_ERROR', mediaError.message, 500);
  }

  // Auto-create default variant "Standard"
  const { data: variant } = await supabase.from('product_variants').insert({
    product_id: product!.id,
    name: 'Standard',
    price_offset: 0,
    is_default: true,
  }).select().single();

  // Stock-backed products start with the explicitly configured quantity. A
  // digital product is file-backed and does not need a finite inventory row.
  if (!body.requiresBooking && body.productType !== 'digital' && variant) {
    await supabase.from('inventory').insert({
      variant_id: variant.id,
      quantity: body.availableStock ?? 0,
      reserved: 0,
      low_stock_threshold: body.lowStockThreshold ?? 5,
    });
  }

  return apiOk(product, { status: 201 });
}

// P2 — Member 2: Booking slot CRUD (B3)

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { slotCreateSchema } from '@/lib/validation/vendor-schemas';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(_request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;
  const request = _request;
  const url = new URL(request.url);
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(50, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const q = (url.searchParams.get('q') || '').trim().replace(/[%(),]/g, ' ');
  const status = url.searchParams.get('status');
  const from = url.searchParams.get('from');
  const to = url.searchParams.get('to');
  const outletId = url.searchParams.get('outletId');
  const productId = url.searchParams.get('productId');

  // Get vendor outlets
  const outletIds = access.access.outletIds;

  let query = supabase
    .from('booking_slots')
    .select('id,product_id,outlet_id,starts_at,ends_at,capacity,booked,price_override,status,products(name,base_price,cover_url),outlets(id,name,city,state)', { count: 'exact' })
    .in('outlet_id', outletIds.length ? outletIds : ['none']);
  if (outletId && outletIds.includes(outletId)) query = query.eq('outlet_id', outletId);
  if (productId) query = query.eq('product_id', productId);
  if (status && status !== 'all') query = query.eq('status', status);
  if (from) query = query.gte('starts_at', from);
  if (to) query = query.lte('starts_at', to);
  if (q) {
    const [{ data: productMatches }, { data: outletMatches }] = await Promise.all([
      supabase.from('products').select('id').eq('vendor_id', vendorId).or(`name.ilike.%${q}%,slug.ilike.%${q}%`).limit(100),
      supabase.from('outlets').select('id').in('id', outletIds.length ? outletIds : ['none']).or(`name.ilike.%${q}%,city.ilike.%${q}%`).limit(100),
    ]);
    const conditions = [
      ...((productMatches || []).map((item: any) => `product_id.eq.${item.id}`)),
      ...((outletMatches || []).map((item: any) => `outlet_id.eq.${item.id}`)),
    ];
    if (!conditions.length) return apiOk({ items: [], pagination: { page, pageSize, total: 0, totalPages: 1 } });
    query = query.or(conditions.join(','));
  }
  const { data, error, count } = await query.order('starts_at').range((page - 1) * pageSize, page * pageSize - 1);

  if (error) return apiFail('DB_ERROR', error.message, 500);
  const items = (data ?? []).map((slot: any) => ({ ...slot, outlets: slot.outlets ? { ...slot.outlets, full_name: slot.outlets.name, name: outletShortName(slot.outlets.name) } : slot.outlets }));
  return apiOk({ items, pagination: { page, pageSize, total: count || 0, totalPages: Math.max(1, Math.ceil((count || 0) / pageSize)) } });
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;

  const parsed = await parseBody(request, slotCreateSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;

  if (!access.access.outletIds.includes(body.outletId)) {
    return apiFail('FORBIDDEN', 'This outlet is outside your assigned scope', 403);
  }

  // Verify product requires booking and belongs to vendor
  const { data: product } = await supabase
    .from('products')
    .select('id, requires_booking')
    .eq('id', body.productId)
    .eq('vendor_id', vendorId)
    .eq('outlet_id', body.outletId)
    .single();
  if (!product) return apiFail('NOT_FOUND', 'Product not found', 404);
  if (!product.requires_booking) {
    return apiFail('INVALID_PRODUCT', 'Product does not require booking — create inventory instead', 400);
  }

  // Verify outlet belongs to vendor
  const { data: outlet } = await supabase
    .from('outlets')
    .select('id')
