  return apiOk(data, { status: 201 });
}

import { apiFail, apiOk } from '@/lib/validation/schemas';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }
type RedemptionRow = { voucher_id: string; discount: number | null; created_at: string; orders: { id?: string; total_amount: number | null } | null };
type VoucherRow = { id: string; code: string; name: string; max_uses: number | null; outlet_id: string | null; outlets: { name: string } | { name: string }[] | null };

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId);
  if (!access.ok) return access.response;
  const url = new URL(request.url);
  const outletId = url.searchParams.get('outletId');
  const from = url.searchParams.get('from');
  const to = url.searchParams.get('to');
  if (outletId && access.access.isOutletManager && !access.access.outletIds.includes(outletId)) return apiFail('FORBIDDEN', 'This outlet is outside your assigned scope', 403);
  if (outletId && !access.access.outletIds.includes(outletId)) return apiFail('FORBIDDEN', 'This outlet is outside your vendor scope', 403);

  const db = access.access.serviceDb;
  let voucherQuery = db.from('vouchers').select('id,code,name,max_uses,outlet_id,outlets(name)').eq('vendor_id', vendorId).order('created_at', { ascending: false });
  if (outletId) voucherQuery = voucherQuery.or(`outlet_id.eq.${outletId},outlet_id.is.null`);
  const { data: vouchers, error: voucherError } = await voucherQuery;
  if (voucherError) return apiFail('DB_ERROR', voucherError.message, 500);
  const voucherRows = (vouchers || []) as VoucherRow[];
  const voucherIds = voucherRows.map((voucher: any) => voucher.id);
  const orderIds = new Set<string>();
  let redemptionQuery = db.from('voucher_redemptions').select('voucher_id,discount,created_at,orders(id,total_amount)').in('voucher_id', voucherIds.length ? voucherIds : ['none']).order('created_at', { ascending: false });
  if (from) redemptionQuery = redemptionQuery.gte('created_at', `${from}T00:00:00+08:00`);
  if (to) redemptionQuery = redemptionQuery.lte('created_at', `${to}T23:59:59.999+08:00`);
  const { data, error } = await redemptionQuery;
  if (error) return apiFail('DB_ERROR', error.message, 500);
  for (const row of (data ?? []) as unknown as RedemptionRow[]) if (row.orders?.id) orderIds.add(row.orders.id);
  let allowedOrderIds: Set<string> | null = null;
  if (outletId && orderIds.size) {
    const { data: orderItems, error: itemError } = await db.from('order_items').select('order_id').in('order_id', [...orderIds]).eq('outlet_id', outletId);
    if (itemError) return apiFail('DB_ERROR', itemError.message, 500);
    allowedOrderIds = new Set((orderItems || []).map((item: any) => item.order_id));
  }
  const analytics = new Map<string, { voucherId: string; code: string; name: string; outletName: string; redemptions: number; redemptionRate: number | null; discount: number; revenue: number; revenueImpact: number }>();
  for (const voucher of voucherRows) {
    const outlet = Array.isArray(voucher.outlets) ? voucher.outlets[0] : voucher.outlets;
    analytics.set(voucher.id, { voucherId: voucher.id, code: voucher.code, name: voucher.name, outletName: outlet?.name || 'All outlets', redemptions: 0, redemptionRate: voucher.max_uses ? 0 : null, discount: 0, revenue: 0, revenueImpact: 0 });
  }
  for (const row of (data ?? []) as unknown as RedemptionRow[]) {
    if (allowedOrderIds && !allowedOrderIds.has(row.orders?.id || '')) continue;
    const current = analytics.get(row.voucher_id);
    if (!current) continue;
    current.redemptions += 1;
    const voucher = voucherRows.find((item) => item.id === row.voucher_id);
    current.redemptionRate = voucher?.max_uses ? Number(((current.redemptions / voucher.max_uses) * 100).toFixed(1)) : null;
    current.discount += Number(row.discount || 0);
    current.revenue += Number(row.orders?.total_amount || 0);
    current.revenueImpact = current.revenue - current.discount;
  }
  return apiOk(Array.from(analytics.values()).sort((a, b) => b.redemptions - a.redemptions || b.revenue - a.revenue));
}

// P2 — Member 2: Voucher CRUD (B3)

import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { voucherCreateSchema } from '@/lib/validation/vendor-schemas';
import { outletShortName } from '@/lib/outlet-display';
import { authorizeVendor } from '@/lib/vendor-authorization';

interface Props { params: Promise<{ vendorId: string }> }

export async function GET(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId, ['vendor_owner']);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;
  const url = new URL(request.url);
  const page = Math.max(1, Number.parseInt(url.searchParams.get('page') || '1', 10) || 1);
  const pageSize = Math.min(50, Math.max(1, Number.parseInt(url.searchParams.get('pageSize') || '10', 10) || 10));
  const q = (url.searchParams.get('q') || '').trim().replace(/[%(),]/g, ' ');
  const statusFilter = url.searchParams.get('status') || 'all';

  let query = supabase.from('vouchers').select('*, outlets(id,name,city,state)', { count: 'exact' }).eq('vendor_id', vendorId).order('created_at', { ascending: false });
  if (access.access.isOutletManager) query = query.in('outlet_id', access.access.outletIds);
  if (q) query = query.or(`code.ilike.%${q}%,name.ilike.%${q}%`);
  const { data, error } = await query;

  if (error) return apiFail('DB_ERROR', error.message, 500);
  const now = Date.now();
  const withStatus = (data ?? []).map((voucher: any) => {
    if (voucher.review_status && voucher.review_status !== 'approved') return { ...voucher, outlets: voucher.outlets ? { ...voucher.outlets, full_name: voucher.outlets.name, name: outletShortName(voucher.outlets.name) } : voucher.outlets, status: voucher.review_status };
    const validFrom = voucher.valid_from ? new Date(voucher.valid_from).getTime() : null;
    const validUntil = voucher.valid_until ? new Date(voucher.valid_until).getTime() : null;
    const status = !voucher.is_active ? 'inactive' : validFrom && validFrom > now ? 'scheduled' : validUntil && validUntil < now ? 'expired' : voucher.max_uses && voucher.uses_count >= voucher.max_uses ? 'expired' : 'active';
    return { ...voucher, outlets: voucher.outlets ? { ...voucher.outlets, full_name: voucher.outlets.name, name: outletShortName(voucher.outlets.name) } : voucher.outlets, status };
  }).filter((voucher: any) => statusFilter === 'all' || voucher.status === statusFilter);
  const start = (page - 1) * pageSize;
  const items = withStatus.slice(start, start + pageSize);
  const stats = withStatus.reduce((result: Record<string, number>, voucher: any) => {
    result[voucher.status] = (result[voucher.status] || 0) + 1;
    return result;
  }, {});
  return apiOk({ items, stats, pagination: { page, pageSize, total: withStatus.length, totalPages: Math.max(1, Math.ceil(withStatus.length / pageSize)) } });
}

export async function POST(request: Request, { params }: Props) {
  const { vendorId } = await params;
  const access = await authorizeVendor(vendorId, ['vendor_owner']);
  if (!access.ok) return access.response;
  const supabase = access.access.serviceDb;

  const { data: vendor } = await supabase
    .from('vendors')
    .select('owner_id, status')
    .eq('id', vendorId)
    .single();
  if (!vendor) return apiFail('FORBIDDEN', 'Not your vendor', 403);
  if (vendor.status !== 'approved') return apiFail('INVALID_STATE', 'Vendor not approved', 400);

  const parsed = await parseBody(request, voucherCreateSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;

  // If outlet specified, verify it belongs to vendor
  if (body.outletId) {
    const { data: outlet } = await supabase
      .from('outlets')
      .select('id')
      .eq('id', body.outletId)
      .eq('vendor_id', vendorId)
      .single();
    if (!outlet) return apiFail('INVALID_OUTLET', 'Outlet not found or not owned by this vendor', 400);
  }

  if (body.voucherType === 'bogo') {
    const { data: product } = await supabase.from('products').select('id').eq('id', body.productId).eq('vendor_id', vendorId).maybeSingle();
    if (!product) return apiFail('INVALID_PRODUCT', 'BOGO product not found for this vendor', 400);
  }

  const { data, error } = await supabase.from('vouchers').insert({
    vendor_id: vendorId,
    outlet_id: body.outletId ?? null,
    code: body.code,
    name: body.name,
    voucher_type: body.voucherType,
    discount_value: body.discountValue ?? 0,
    min_spend: body.minSpend,
    max_uses: body.maxUses ?? null,
    valid_from: body.validFrom ?? null,
    valid_until: body.validUntil ?? null,
    product_id: body.productId ?? null,
    buy_quantity: body.buyQuantity ?? null,
    free_quantity: body.freeQuantity ?? null,
    is_active: false,
    review_status: 'pending_review',
  }).select().single();

  if (error) {
    if (error.message.includes('unique') || error.message.includes('duplicate')) {
      return apiFail('CODE_TAKEN', `Voucher code "${body.code}" is already in use`, 409);
    }
    return apiFail('DB_ERROR', error.message, 400);
  }
  return apiOk(data, { status: 201 });
}

// P2 — Member 2 owns GET /api/vendors + POST /api/vendors

import { createClient } from '@/lib/supabase/server';
import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { vendorRegisterSchema } from '@/lib/validation/vendor-schemas';
import { slugify } from '@/lib/utils';

export async function GET(request: Request) {
  const supabase = await createClient();
  const url = new URL(request.url);
  const city     = url.searchParams.get('city');
  const category = url.searchParams.get('category');
  const status   = url.searchParams.get('status');
  const q        = url.searchParams.get('q');

  let query = supabase
    .from('vendors')
    .select('*, outlets(id, name, city, lat, lng, status)')
    .eq('status', status ?? 'approved');

  if (q) query = query.ilike('name', `%${q}%`);
  if (city) query = query.contains('outlets', [{ city }]);

  const { data, error } = await query.order('created_at', { ascending: false }).limit(50);
  if (error) return apiFail('DB_ERROR', error.message, 500);

  // If category filter, post-filter vendors that have products in that category
  let filtered = data ?? [];
  if (category) {
    const vendorIds = filtered.map((v: any) => v.id);
    const { data: products } = await supabase
      .from('products')
      .select('vendor_id, categories(slug)')
      .in('vendor_id', vendorIds.length ? vendorIds : ['none'])
      .eq('status', 'active');

    const matchingVendorIds = new Set(
      (products ?? [])
        .filter((p: any) => (p.categories as Record<string, any>)?.slug === category)
        .map((p: any) => p.vendor_id),
    );
    filtered = filtered.filter((v: any) => matchingVendorIds.has(v.id));
  }

  return apiOk(filtered);
}

export async function POST(request: Request) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return apiFail('UNAUTHORIZED', 'Sign in required', 401);

  const parsed = await parseBody(request, vendorRegisterSchema);
  if (!parsed.ok) return parsed.response;
  const body = parsed.data;

  // Check if user already has a vendor
  const { data: existing } = await supabase
    .from('vendors')
    .select('id, status')
    .eq('owner_id', user.id)
    .in('status', ['pending', 'approved'])
    .limit(1);

  if (existing && existing.length > 0) {
    return apiFail('DUPLICATE', `You already have a vendor (status: ${existing[0].status})`, 409);
  }

  // Generate slug if not provided
  const finalSlug = body.slug || slugify(body.name);

  // Check slug uniqueness
  const { data: slugCheck } = await supabase
    .from('vendors')
    .select('id')
    .eq('slug', finalSlug)
    .limit(1);

  if (slugCheck && slugCheck.length > 0) {
    return apiFail('SLUG_TAKEN', `Slug "${finalSlug}" is already in use`, 409);
  }

  const { data, error } = await supabase.from('vendors').insert({
    owner_id: user.id,
    name: body.name,
    slug: finalSlug,
    description: body.description ?? null,
    business_type: body.businessType ?? null,
    logo_url: body.logoUrl || null,
    cover_url: body.coverUrl || null,
    status: 'pending',
  }).select().single();

  if (error) return apiFail('DB_ERROR', error.message, 400);
  return apiOk(data, { status: 201 });
}

// P2 — Member 2: Voucher validation contract (B3)
// Used by Member 4 (D1 Cart/Checkout) to validate voucher codes
// POST /api/vouchers/validate

import { createClient } from '@/lib/supabase/server';
import { parseBody, apiOk, apiFail } from '@/lib/validation/schemas';
import { voucherValidateSchema } from '@/lib/validation/vendor-schemas';
import { applyPercent } from '@/lib/money';

export async function POST(request: Request) {
  const supabase = await createClient();

  const parsed = await parseBody(request, voucherValidateSchema);
  if (!parsed.ok) return parsed.response;
  const { code, cartSubtotal, vendorId, items } = parsed.data;

  // Find voucher
  const { data: voucher } = await supabase
    .from('vouchers')
    .select('*')
    .eq('code', code)
    .single();

  if (!voucher) {
    return apiOk({ valid: false, reason: 'Voucher code not found' });
  }

  // Check active
  if (!voucher.is_active) {
    return apiOk({ valid: false, reason: 'This voucher is no longer active' });
  }

  // Check vendor match (if vendorId provided)
  if (vendorId && voucher.vendor_id !== vendorId) {
    return apiOk({ valid: false, reason: 'This voucher is not valid for this vendor' });
  }

  // Check validity period
  const now = new Date();
  if (voucher.valid_from && new Date(voucher.valid_from) > now) {
    return apiOk({ valid: false, reason: 'This voucher is not yet valid' });
  }
  if (voucher.valid_until && new Date(voucher.valid_until) < now) {
    return apiOk({ valid: false, reason: 'This voucher has expired' });
  }

  // Check usage limit
  if (voucher.max_uses !== null && voucher.uses_count >= voucher.max_uses) {
    return apiOk({ valid: false, reason: 'This voucher has reached its usage limit' });
  }

  // Check minimum spend
  if (cartSubtotal < voucher.min_spend) {
    return apiOk({
      valid: false,
      reason: `Minimum spend of RM ${voucher.min_spend.toFixed(2)} required (current: RM ${cartSubtotal.toFixed(2)})`,
    });
  }

  if (voucher.review_status && voucher.review_status !== 'approved') {
    return apiOk({ valid: false, reason: 'This voucher is still awaiting approval' });
  }

  // Calculate discount
  let discountAmount: number;
  if (voucher.voucher_type === 'bogo') {
    const eligible = (items ?? []).find((item) => item.productId === voucher.product_id);
    const buyQuantity = Number(voucher.buy_quantity ?? 0);
    const freeQuantity = Number(voucher.free_quantity ?? 0);
    if (!eligible || buyQuantity < 1 || freeQuantity < 1) {
      return apiOk({ valid: false, reason: 'Add the eligible product to your cart to use this voucher' });
    }
    discountAmount = Math.min(cartSubtotal, Math.floor(eligible.quantity / buyQuantity) * freeQuantity * eligible.unitPrice);
  } else if (voucher.voucher_type === 'percent') {
    discountAmount = applyPercent(cartSubtotal, voucher.discount_value);
  } else {
    // Fixed amount — cannot exceed cart subtotal
    discountAmount = Math.min(voucher.discount_value, cartSubtotal);
  }

  return apiOk({
    valid: true,
    voucherId: voucher.id,
    vendorId: voucher.vendor_id,
    outletId: voucher.outlet_id,
    voucherType: voucher.voucher_type,
    discountValue: voucher.discount_value,
    discountAmount,
    code: voucher.code,
    name: voucher.name,
  });
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Bike, Bus, Car, CheckCircle, Clock, Footprints, Globe, MapPin, MessageCircle, Navigation, Phone, Star, Tag, Users } from "lucide-react";
import { getOrCreateThread } from "@/backend/domains/identity";
import { useAuth } from "@/components/providers/auth";
import { useCart } from "@/components/providers/cart";
import { unitPrice } from "@/backend/core/helpers";
import { AiTag } from "@/components/customer/ai-tag";
import { MapView } from "@/components/map/map-view";
import { EmptyState } from "@/components/shared/empty-state";
import { ShareButton } from "@/components/shared/share-button";
import { Button } from "@/components/ui/button";
import type { BookingSlot, ComputedActivity } from "@/backend/core/types";

const TRAVEL_MODES = [
  { id: "DRIVING", urlParam: "driving", label: "Drive", icon: Car },
  { id: "WALKING", urlParam: "walking", label: "Walk", icon: Footprints },
  { id: "BICYCLING", urlParam: "bicycling", label: "Cycle", icon: Bike },
  { id: "TRANSIT", urlParam: "transit", label: "Transit", icon: Bus },
] as const;
type TravelModeId = (typeof TRAVEL_MODES)[number]["id"];

type DetailChip = { label: string; value: string; icon: typeof Clock; href?: string };

// Food & Dining gets real, category-relevant chips; every other category keeps
// the original generic set until they get their own pass.
function getDetailChips(activity: ComputedActivity): DetailChip[] {
  if (activity.category !== "Food & Dining") {
    return [
      { label: "Duration", value: activity.duration, icon: Clock },
      { label: "Group Size", value: "2–12 pax", icon: Users },
      { label: "Language", value: "EN / BM", icon: Globe },
    ];
  }
  const chips: DetailChip[] = [];
  if (activity.outlet.hours) chips.push({ label: "Hours", value: activity.outlet.hours, icon: Clock });
  if (activity.tags && activity.tags.length > 0) chips.push({ label: "Tags", value: activity.tags.join(" · "), icon: Tag });
  if (activity.outlet.phone) chips.push({ label: "Contact", value: activity.outlet.phone, icon: Phone, href: `tel:${activity.outlet.phone}` });
  return chips;
}

export function ActivityDetailClient({
  initialActivity,
  initialSlots,
}: {
  initialActivity: ComputedActivity | null;
  initialSlots: BookingSlot[];
}) {
  const router = useRouter();
  const { currentUser } = useAuth();
  const { addItem } = useCart();

  const [activity] = useState<ComputedActivity | null>(initialActivity);
  const [slots] = useState<BookingSlot[]>(initialSlots);
  const [variantId, setVariantId] = useState<string>(initialActivity?.variants[0]?.id ?? "");
  const [slotId, setSlotId] = useState<string>("");
  const [qty, setQty] = useState(1);
  const [adding, setAdding] = useState(false);
  const [added, setAdded] = useState(false);
  const [travelMode, setTravelMode] = useState<TravelModeId>("DRIVING");
  const [userLoc, setUserLoc] = useState<{ lat: number; lng: number } | null>(null);
  const [mapsReady, setMapsReady] = useState(false);
  const [eta, setEta] = useState<{ durationText: string; distanceText: string } | null>(null);
  const [etaStatus, setEtaStatus] = useState<"idle" | "loading" | "denied" | "error">("idle");
  const [view, setView] = useState<"details" | "map">("details");

  const price = useMemo(() => (activity ? unitPrice(activity, variantId) : 0), [activity, variantId]);
  const selectedSlot = slots.find((s) => s.id === slotId);
  const seatsLeft = selectedSlot ? selectedSlot.capacity - selectedSlot.booked : undefined;

  // A slot switch can leave qty above the new slot's remaining seats — clamp down.
  useEffect(() => {
    if (selectedSlot) setQty((q) => Math.min(q, Math.max(1, selectedSlot.capacity - selectedSlot.booked)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slotId]);

  // Retries the ETA calc once the Maps script finishes loading, covering the
  // race where the user picks a travel mode before google.maps is ready.
  useEffect(() => {
    if (mapsReady && userLoc && activity) computeEta(userLoc, travelMode);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mapsReady]);

  function computeEta(origin: { lat: number; lng: number }, mode: TravelModeId) {
    if (!mapsReady || !activity) return;
    setEtaStatus("loading");
    new google.maps.DirectionsService()
      .route({
        origin,
        destination: { lat: activity.outlet.lat, lng: activity.outlet.lng },
        travelMode: google.maps.TravelMode[mode],
      })
      .then((result) => {
        const leg = result.routes[0]?.legs[0];
        if (!leg?.duration || !leg.distance) throw new Error("no route");
        setEta({ durationText: leg.duration.text, distanceText: leg.distance.text });
        setEtaStatus("idle");
      })
      .catch(() => {
        setEta(null);
        setEtaStatus("error");
      });
  }

  function handleTravelModeChange(mode: TravelModeId) {
    setTravelMode(mode);
    setEta(null);
    if (userLoc) {
      computeEta(userLoc, mode);
      return;
    }
    if (!navigator.geolocation) {
      setEtaStatus("denied");
      return;
    }
    setEtaStatus("loading");
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        setUserLoc(loc);
        computeEta(loc, mode);
      },
      () => setEtaStatus("denied"),
      { timeout: 5000 },
    );
  }

  if (activity === null) {
    return <EmptyState title="Experience not found" description="This listing may have been removed." />;
  }

  function handleAddToCart() {
    if (adding) return; // double-submit guard
    if (activity!.requiresBooking && !slotId) return;
    setAdding(true);
    addItem({ activityId: activity!.id, variantId, slotId: slotId || undefined, qty });
    setAdded(true);
    setTimeout(() => {
      setAdding(false);
    }, 400);
  }

  function handleDirections() {
    const params = new URLSearchParams({
      api: "1",
      destination: `${activity!.outlet.lat},${activity!.outlet.lng}`,
      travelmode: TRAVEL_MODES.find((m) => m.id === travelMode)!.urlParam,
    });
    if (userLoc) params.set("origin", `${userLoc.lat},${userLoc.lng}`);
    window.open(`https://www.google.com/maps/dir/?${params.toString()}`, "_blank");
  }

  async function handleChat() {
    if (!currentUser) return;
    const thread = await getOrCreateThread(currentUser.id, activity!.outletId);
    router.push(`/customer/chat/${thread.id}`);
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-6 sm:py-8">
      <div className="relative rounded-2xl overflow-hidden mb-6" style={{ height: 280 }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={activity.image} alt={activity.name} className="w-full h-full object-cover" />
        <div className="absolute inset-0" style={{ background: "linear-gradient(to top, rgba(36,49,58,0.65) 0%, transparent 50%)" }} />
        {activity.outlet.verified && (
          <div className="absolute bottom-4 left-5 flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-semibold text-white bg-primary">
            <CheckCircle size={13} /> Verified Vendor
          </div>
        )}
      </div>

      <div className="flex items-start justify-between gap-4 mb-4 flex-wrap">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold leading-tight mb-2 text-foreground font-[family-name:var(--font-display)]">{activity.name}</h1>
          <div className="flex items-center gap-4 flex-wrap text-sm">
            <div className="flex items-center gap-1.5 text-muted-foreground">
              <MapPin size={13} /> {activity.outlet.city}, {activity.outlet.state}
            </div>
            <div className="flex items-center gap-1.5">
              <Star size={13} fill="var(--highlight-yellow)" stroke="none" />
              <span className="font-bold text-foreground">{activity.rating}</span>
              <span className="text-muted-foreground">({activity.reviews} reviews)</span>
            </div>
            <div className="flex items-center gap-1.5" style={{ color: activity.outlet.open ? "var(--nature-green-ink)" : "#64748b" }}>
              <span className="h-2 w-2 rounded-full" style={{ backgroundColor: activity.outlet.open ? "var(--nature-green)" : "#94a3b8" }} />
              {activity.outlet.open ? "Open Now" : "Currently Closed"}
            </div>
          </div>
        </div>
        <div className="text-right shrink-0">
          <p className="text-3xl font-bold text-primary font-[family-name:var(--font-mono)]">RM {price}</p>
          <p className="text-xs text-muted-foreground">per person</p>
        </div>
      </div>

      <div className="flex items-center gap-1 p-1 rounded-full border border-border w-fit mb-6">
        {(["details", "map"] as const).map((v) => (
          <button
            key={v}
            onClick={() => setView(v)}
            className="px-4 py-1.5 rounded-full text-xs font-semibold capitalize"
            style={{ backgroundColor: view === v ? "var(--primary)" : "transparent", color: view === v ? "white" : "var(--foreground)" }}
          >
            {v}
          </button>
        ))}
      </div>

      {view === "details" && (
        <>
          {activity.aiTag && <div className="mb-4"><AiTag text={activity.aiTag} /></div>}

          <p className="text-sm leading-relaxed mb-6 text-foreground/80">{activity.description}</p>

          {getDetailChips(activity).length > 0 && (
            <div className="grid grid-cols-3 gap-3 mb-6">
              {getDetailChips(activity).map((d) => {
                const content = (
                  <>
                    <div className="flex justify-center mb-1 text-teal"><d.icon size={15} /></div>
                    <p className="text-[10px] uppercase tracking-wide mb-0.5 text-muted-foreground">{d.label}</p>
                    <p className="text-sm font-bold text-foreground truncate">{d.value}</p>
                  </>
                );
                return d.href ? (
                  <a key={d.label} href={d.href} className="rounded-xl p-3 text-center bg-muted block">{content}</a>
                ) : (
                  <div key={d.label} className="rounded-xl p-3 text-center bg-muted">{content}</div>
                );
              })}
            </div>
          )}

          {/* Booking selection */}
          <div className="rounded-xl p-4 mb-6 border border-border">
            <p className="text-xs font-bold uppercase tracking-wider mb-3 text-primary">
              {activity.requiresBooking ? "Select Date & Package" : "Choose Options"}
            </p>

            {activity.variants.length > 1 && (
              <div className="mb-3">
                <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Package</label>
                <div className="flex gap-2 flex-wrap">
                  {activity.variants.map((v) => (
                    <button
                      key={v.id}
                      onClick={() => setVariantId(v.id)}
                      className="px-3 py-2 rounded-lg text-xs font-semibold border"
                      style={{
                        borderColor: variantId === v.id ? "var(--primary)" : "var(--border)",
                        backgroundColor: variantId === v.id ? "var(--primary)" : "transparent",
                        color: variantId === v.id ? "white" : "var(--foreground)",
                      }}
                    >
                      {v.label} {v.priceDelta !== 0 && `(${v.priceDelta > 0 ? "+" : ""}RM ${v.priceDelta})`}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {activity.requiresBooking && (
              <div className="mb-3">
                <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Time Slot</label>
                {slots.length === 0 ? (
                  <p className="text-xs text-muted-foreground">No slots available yet.</p>
                ) : (
                  <div className="flex gap-2 flex-wrap">
                    {slots.map((s) => {
                      const full = s.booked >= s.capacity;
                      return (
                        <button
                          key={s.id}
                          disabled={full}
                          onClick={() => setSlotId(s.id)}
                          className="px-3 py-2 rounded-lg text-xs font-semibold border disabled:opacity-40 disabled:cursor-not-allowed"
                          style={{
                            borderColor: slotId === s.id ? "var(--primary)" : "var(--border)",
                            backgroundColor: slotId === s.id ? "var(--primary)" : "transparent",
                            color: slotId === s.id ? "white" : "var(--foreground)",
                          }}
                        >
                          {new Date(s.startsAt).toLocaleString("en-MY", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}
                          {full ? " · Full" : ` · ${s.capacity - s.booked} left`}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center gap-3">
              <label className="text-xs font-semibold text-muted-foreground">Quantity</label>
              <div className="flex items-center gap-2">
                <button onClick={() => setQty((q) => Math.max(1, q - 1))} className="w-7 h-7 rounded-lg border border-border text-foreground">−</button>
                <span className="w-6 text-center text-sm font-semibold text-foreground">{qty}</span>
                <button
                  onClick={() => setQty((q) => (seatsLeft !== undefined ? Math.min(seatsLeft, q + 1) : q + 1))}
                  disabled={seatsLeft !== undefined && qty >= seatsLeft}
                  className="w-7 h-7 rounded-lg border border-border text-foreground disabled:cursor-not-allowed disabled:opacity-40"
                >
                  +
                </button>
              </div>
              {seatsLeft !== undefined && <span className="text-xs text-muted-foreground">{seatsLeft} seats left</span>}
            </div>
          </div>

          <div className="flex gap-3 mb-8 flex-wrap">
            <Button
              onClick={handleAddToCart}
              disabled={adding || (activity.requiresBooking && !slotId)}
              className="flex-1 min-w-[140px] h-12 rounded-full text-base"
            >
              {added ? "Added to Cart ✓" : activity.requiresBooking ? "Add Booking to Cart" : "Add to Cart"}
            </Button>
            <Button variant="outline" size="icon" className="w-12 h-12 rounded-full border-2" onClick={handleChat} title="Chat with vendor">
              <MessageCircle size={18} />
            </Button>
            <ShareButton productId={activity.id} productName={activity.name} />
          </div>
          {activity.requiresBooking && !slotId && (
            <p className="text-xs text-destructive -mt-6 mb-6">Select a time slot to continue.</p>
          )}
        </>
      )}

      {view === "map" && (
        <>
          <div className="flex items-center gap-2 mb-4 flex-wrap">
            <span className="text-xs font-semibold text-muted-foreground mr-1">Directions:</span>
            {TRAVEL_MODES.map((m) => (
              <button
                key={m.id}
                onClick={() => handleTravelModeChange(m.id)}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold border"
                style={{
                  borderColor: travelMode === m.id ? "var(--travel-blue)" : "var(--border)",
                  backgroundColor: travelMode === m.id ? "var(--travel-blue)" : "transparent",
                  color: travelMode === m.id ? "white" : "var(--foreground)",
                }}
              >
                <m.icon size={13} /> {m.label}
              </button>
            ))}
            <span className="text-xs text-muted-foreground ml-1">
              {etaStatus === "loading" && "Calculating…"}
              {etaStatus === "denied" && "Enable location for ETA"}
              {etaStatus === "error" && "ETA unavailable"}
              {etaStatus === "idle" && eta && `${eta.durationText} · ${eta.distanceText}`}
            </span>
          </div>

          <Button variant="default" onClick={handleDirections} className="mb-4 rounded-full bg-primary text-white hover:bg-primary/90">
            <Navigation size={16} className="mr-1.5" /> Get Directions
          </Button>

          <div>
            <p className="text-sm font-bold text-foreground mb-2">Location</p>
            <MapView
              pins={[{ id: activity.outlet.id, lat: activity.outlet.lat, lng: activity.outlet.lng, label: activity.outlet.name, sublabel: activity.outlet.address }]}
              center={[activity.outlet.lat, activity.outlet.lng]}
              zoom={14}
              height={420}
              onApiLoaded={() => setMapsReady(true)}
            />
          </div>
        </>
      )}
    </div>
  );
}

