"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { AlertCircle, CreditCard, ShieldCheck, Smartphone, Wallet } from "lucide-react";
import { useAuth } from "@/components/providers/auth";
import { useCart } from "@/components/providers/cart";
import { createOrder } from "@/backend/domains/commerce";
import { getVoucherByCode } from "@/backend/domains/catalogue";
import { EmptyState } from "@/components/shared/empty-state";
import { Button } from "@/components/ui/button";
import type { Voucher } from "@/backend/core/types";

const METHODS = [
  { id: "stripe_card", label: "Card via Stripe Test Mode", icon: CreditCard },
  { id: "ewallet", label: "Touch 'n Go / GrabPay", icon: Smartphone },
  { id: "bank_transfer", label: "Bank transfer (demo)", icon: CreditCard },
  { id: "wallet", label: "MyWisata Wallet Balance", icon: Wallet },
];

export default function CheckoutPage() {
  const router = useRouter();
  const { currentUser } = useAuth();
  const { selectedItems, selectedKeys, totals } = useCart();
  const [voucherCode, setVoucherCode] = useState<string | null>(null);
  const [voucher, setVoucher] = useState<Voucher | undefined>(undefined);
  const [method, setMethod] = useState("stripe_card");
  const [paying, setPaying] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setVoucherCode(new URLSearchParams(window.location.search).get("voucher"));
  }, []);

  useEffect(() => {
    if (voucherCode) getVoucherByCode(voucherCode).then(setVoucher);
  }, [voucherCode]);

  useEffect(() => {
    const sessionId = new URLSearchParams(window.location.search).get("stripe_session_id");
    if (!sessionId || !currentUser || selectedItems.length === 0 || paying) return;
    setPaying(true);
    createOrder(currentUser.id, voucherCode ?? undefined, "stripe_card", [...selectedKeys]).then((order) => router.push(`/customer/orders/${order.id}`)).catch(() => { setFailed(true); setPaying(false); });
  }, [currentUser, selectedItems.length, selectedKeys, paying, router, voucherCode]);

  const { subtotal, discount, total } = totals(voucher);

  if (selectedItems.length === 0) {
    return <EmptyState title="Nothing to check out" description="Select at least one item in your cart to continue." />;
  }

  function handlePay(shouldSucceed: boolean) {
    if (paying) return; // double-submit guard
    setPaying(true);
    setFailed(false);
    setTimeout(async () => {
      if (!shouldSucceed) {
        setFailed(true);
        setPaying(false);
        return;
      }
      try {
        const order = await createOrder(currentUser!.id, voucherCode ?? undefined, method as "mock_card" | "ewallet" | "bank_transfer" | "wallet" | "stripe_card", [...selectedKeys]);
        router.push(`/customer/orders/${order.id}`);
      } catch (err) {
        console.error("Order creation failed:", err);
        setFailed(true);
        setPaying(false);
      }
    }, 600);
  }

  return (
    <div className="max-w-lg mx-auto px-4 sm:px-6 py-8">
      <h1 className="text-2xl font-bold text-foreground mb-2 font-[family-name:var(--font-display)]">Checkout</h1>
      <p className="text-xs text-muted-foreground mb-6 flex items-center gap-1.5">
        <ShieldCheck size={13} /> Demo / Mock payment — no real money moves.
      </p>

      <div className="rounded-xl border border-border p-4 mb-6 space-y-2">
        <div className="flex justify-between text-sm">
          <span className="text-muted-foreground">Subtotal</span>
          <span className="font-semibold text-foreground font-[family-name:var(--font-mono)]">RM {subtotal.toFixed(2)}</span>
        </div>
        {discount > 0 && (
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Discount ({voucherCode})</span>
            <span className="font-semibold text-primary font-[family-name:var(--font-mono)]">− RM {discount.toFixed(2)}</span>
          </div>
        )}
        <div className="flex justify-between text-base pt-2 border-t border-border">
          <span className="font-bold text-foreground">Total</span>
          <span className="font-bold text-primary font-[family-name:var(--font-mono)]">RM {total.toFixed(2)}</span>
        </div>
      </div>

      <p className="text-xs font-semibold text-muted-foreground mb-2">Payment method</p>
      <div className="space-y-2 mb-6">
        {METHODS.map((m) => (
          <button
            key={m.id}
            onClick={() => setMethod(m.id)}
            className="w-full flex items-center gap-3 p-3 rounded-xl border text-left"
            style={{ borderColor: method === m.id ? "var(--primary)" : "var(--border)", backgroundColor: method === m.id ? "color-mix(in srgb, var(--primary) 8%, transparent)" : "transparent" }}
          >
            <m.icon size={16} className="text-teal shrink-0" />
            <span className="text-sm font-medium text-foreground">{m.label}</span>
          </button>
        ))}
      </div>

      {failed && (
        <div className="flex items-center gap-2 p-3 rounded-xl bg-destructive/10 text-destructive text-sm mb-4">
          <AlertCircle size={15} /> Payment failed (demo). Please try again.
        </div>
      )}

      <div className="flex gap-3">
        <Button className="flex-1 h-12 rounded-full" disabled={paying} onClick={() => handlePay(true)}>
          {paying ? "Processing…" : "Pay (Success)"}
        </Button>
        <Button variant="outline" className="flex-1 h-12 rounded-full" disabled={paying} onClick={() => handlePay(false)}>
          Pay (Fail — demo)
        </Button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import { CheckCircle2, Package, QrCode } from "lucide-react";
import { getBookingsForOrder, getOrder } from "@/backend/domains/commerce";
import { StatusBadge } from "@/components/shared/status-badge";
import { EmptyState } from "@/components/shared/empty-state";
import { Button } from "@/components/ui/button";
import type { Booking, Order } from "@/backend/core/types";

export default function OrderDetailPage() {
  const params = useParams<{ id: string }>();
  const [order, setOrder] = useState<Order | null | undefined>(undefined);
  const [bookings, setBookings] = useState<Booking[]>([]);

  useEffect(() => {
    (async () => {
      const o = (await getOrder(params.id)) ?? null;
      setOrder(o);
      if (o) setBookings(await getBookingsForOrder(o.id));
    })();
  }, [params.id]);

  if (order === undefined) {
    return <div className="max-w-lg mx-auto px-6 py-16 text-sm text-muted-foreground">Loading…</div>;
  }
  if (order === null) {
    return <EmptyState title="Order not found" />;
  }

  return (
    <div className="order-receipt-page mx-auto max-w-lg px-4 py-8 sm:px-6 print:max-w-none print:px-0 print:py-0">
      {order.status === "PAID" || order.status === "COMPLETED" ? (
        <div className="flex flex-col items-center text-center mb-8">
          <div className="w-16 h-16 rounded-full flex items-center justify-center mb-3 bg-primary/15">
            <CheckCircle2 size={36} className="text-primary" />
          </div>
          <h1 className="text-xl font-bold text-foreground font-[family-name:var(--font-display)]">Booking Confirmed!</h1>
          <p className="text-sm text-muted-foreground">Your adventure is locked in.</p>
        </div>
      ) : (
        <h1 className="text-xl font-bold text-foreground mb-6 font-[family-name:var(--font-display)]">Order Details</h1>
      )}

      <div className="rounded-xl border border-border p-4 mb-4">
        <div className="flex items-center justify-between mb-3">
          <span className="text-xs font-semibold text-muted-foreground font-[family-name:var(--font-mono)]">#{order.id}</span>
          <StatusBadge status={order.status} />
        </div>
        <div className="space-y-2 mb-3">
          {order.items.map((item, i) => (
            <div key={i} className="flex items-center gap-3 text-sm">
              <div className="flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-secondary text-primary print:h-16 print:w-16">
                {item.imageUrl ? <img src={item.imageUrl} alt={item.activityName} className="h-full w-full object-cover" /> : <Package size={22} />}
              </div>
              <span className="min-w-0 flex-1 text-foreground">{item.qty}× {item.activityName} ({item.variantLabel})</span>
              <span className="font-semibold text-foreground font-[family-name:var(--font-mono)]">RM {(item.unitPrice * item.qty).toFixed(2)}</span>
            </div>
          ))}
        </div>
        <div className="pt-3 border-t border-border space-y-1">
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>Subtotal</span><span>RM {order.subtotal.toFixed(2)}</span>
          </div>
          {order.discount > 0 && (
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Discount {order.voucherCode && `(${order.voucherCode})`}</span><span>− RM {order.discount.toFixed(2)}</span>
            </div>
          )}
          <div className="flex justify-between text-sm font-bold text-foreground pt-1">
            <span>Total Paid</span><span className="text-primary font-[family-name:var(--font-mono)]">RM {order.total.toFixed(2)}</span>
          </div>
        </div>
      </div>

      {bookings.length > 0 && (
        <div className="space-y-3 mb-6">
          <p className="text-sm font-bold text-foreground">Your Bookings</p>
          {bookings.map((b) => (
            <div key={b.id} className="rounded-xl border border-border p-4 flex items-center gap-4">
              <div className="w-16 h-16 rounded-lg flex items-center justify-center shrink-0 bg-primary/10">
                <QrCode size={32} className="text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-foreground truncate">{b.activityName}</p>
                {b.slotStartsAt && (
                  <p className="text-xs text-muted-foreground">
                    {new Date(b.slotStartsAt).toLocaleString("en-MY", { day: "numeric", month: "short", hour: "numeric", minute: "2-digit" })}
                  </p>
                )}
                <p className="text-xs font-mono text-muted-foreground mt-0.5">{b.qrCode} (Demo QR)</p>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="flex gap-3 print:hidden">
        <Button type="button" variant="outline" className="flex-1" onClick={() => window.print()}>Print receipt</Button>
        <Link href="/customer/activity?tab=orders" className="flex-1"><Button variant="outline" className="w-full">Back to Order History</Button></Link>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { CalendarDays, ChevronLeft, ChevronRight, CircleCheck, Clock3, Package, ReceiptText, Search, SlidersHorizontal, X } from "lucide-react";
import { useAuth } from "@/components/providers/auth";
import { getOrdersForUser } from "@/backend/domains/commerce";
import { getOutlets } from "@/backend/domains/catalogue";
import { supabase } from "@/backend/supabase";
import { EmptyState } from "@/components/shared/empty-state";
import { StatusBadge } from "@/components/shared/status-badge";
import { Button } from "@/components/ui/button";
import type { Order, Outlet } from "@/backend/core/types";
import { activityHref } from "@/lib/customer/activity-navigation";

type OrderFilterStatus = "all" | "PAID" | "COMPLETED" | "CANCELLED" | "REFUNDED" | "PENDING_PAYMENT";
type OrderFilterType = "all" | "booking" | "product" | "mixed";

const STATUS_OPTIONS: { value: OrderFilterStatus; label: string }[] = [
  { value: "all", label: "All statuses" },
  { value: "PAID", label: "Paid" },
  { value: "COMPLETED", label: "Completed" },
  { value: "PENDING_PAYMENT", label: "Pending payment" },
  { value: "CANCELLED", label: "Cancelled" },
  { value: "REFUNDED", label: "Refunded" },
];
const PAGE_SIZE = 10;

function shortOrderId(id: string) { return `#${id.slice(0, 8).toUpperCase()}`; }
function orderType(order: Order): Exclude<OrderFilterType, "all"> {
  const hasBooking = order.items.some((item) => Boolean(item.slotStartsAt));
  const hasProduct = order.items.some((item) => !item.slotStartsAt);
  return hasBooking && hasProduct ? "mixed" : hasBooking ? "booking" : "product";
}
function typeLabel(type: Exclude<OrderFilterType, "all">) { return type === "mixed" ? "Mixed order" : type === "booking" ? "Booking" : "Product"; }
function paymentLabel(method?: string) { return ({ stripe_card: "Stripe demo card", ewallet: "E-wallet", bank_transfer: "Bank transfer", wallet: "MyWisata wallet", mock_card: "Demo card" } as Record<string, string>)[method ?? ""] || "Demo payment"; }
function dateLabel(value: string) { return new Date(value).toLocaleDateString("en-MY", { day: "numeric", month: "short", year: "numeric" }); }
function matchesDate(value: string, from: string, to: string) {
  const time = new Date(value).getTime();
  if (from && time < new Date(`${from}T00:00:00`).getTime()) return false;
  if (to && time > new Date(`${to}T23:59:59`).getTime()) return false;
  return true;
}

export default function OrdersPage() {
  const { currentUser } = useAuth();
  const [orders, setOrders] = useState<Order[] | null>(null);
  const [outlets, setOutlets] = useState<Outlet[]>([]);
  const [error, setError] = useState("");
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<OrderFilterStatus>("all");
  const [type, setType] = useState<OrderFilterType>("all");
  const [outletId, setOutletId] = useState("all");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [page, setPage] = useState(1);

  useEffect(() => {
    if (!currentUser) return;
    let active = true;
    const load = async () => {
      try {
        const [nextOrders, nextOutlets] = await Promise.all([getOrdersForUser(currentUser.id), getOutlets()]);
        if (active) { setOrders(nextOrders); setOutlets(nextOutlets); setError(""); }
      } catch (reason) {
        if (active) { setError(reason instanceof Error ? reason.message : "Could not load your orders."); setOrders([]); }
      }
    };
    void load();
    const channel = supabase
      .channel(`customer-orders-${currentUser.id}`)
      .on("postgres_changes", { event: "*", schema: "public", table: "orders", filter: `user_id=eq.${currentUser.id}` }, () => { void load(); })
      .on("postgres_changes", { event: "*", schema: "public", table: "bookings", filter: `customer_id=eq.${currentUser.id}` }, () => { void load(); })
      .subscribe();
    return () => { active = false; void supabase.removeChannel(channel); };
  }, [currentUser]);

  const outletMap = useMemo(() => new Map(outlets.map((outlet) => [outlet.id, outlet])), [outlets]);
  const filteredOrders = useMemo(() => {
    const needle = query.trim().toLowerCase();
    return (orders ?? []).filter((order) => {
      if (status !== "all" && order.status !== status) return false;
      if (type !== "all" && orderType(order) !== type) return false;
      if (outletId !== "all" && !order.items.some((item) => item.outletId === outletId)) return false;
      if (!matchesDate(order.createdAt, from, to)) return false;
      if (needle && ![order.id, ...order.items.flatMap((item) => [item.activityName, item.variantLabel, outletMap.get(item.outletId)?.name || ""])].join(" ").toLowerCase().includes(needle)) return false;
      return true;
    });
  }, [from, outletId, orders, outletMap, query, status, to, type]);

  const pageCount = Math.max(1, Math.ceil(filteredOrders.length / PAGE_SIZE));
  const visiblePage = Math.min(page, pageCount);
  const pagedOrders = filteredOrders.slice((visiblePage - 1) * PAGE_SIZE, visiblePage * PAGE_SIZE);

  const stats = useMemo(() => ({
    total: orders?.length ?? 0,
    paid: (orders ?? []).filter((order) => order.status === "PAID" || order.status === "COMPLETED").length,
    bookings: (orders ?? []).filter((order) => orderType(order) !== "product").length,
  }), [orders]);

  function clearFilters() { setQuery(""); setStatus("all"); setType("all"); setOutletId("all"); setFrom(""); setTo(""); }
  const hasFilters = Boolean(query || status !== "all" || type !== "all" || outletId !== "all" || from || to);

  if (orders === null) return <div className="mx-auto max-w-6xl px-4 py-16 text-sm text-muted-foreground">Loading your orders…</div>;

  return (
    <div className="min-h-full bg-background">
      <div className="mx-auto max-w-6xl px-4 py-8 sm:px-6 sm:py-12">
        <header className="flex flex-col gap-5 md:flex-row md:items-end md:justify-between">
          <div>
            <p className="mb-2 inline-flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.2em] text-primary"><ReceiptText size={14} /> Trip ledger</p>
            <h1 className="font-[family-name:var(--font-display)] text-3xl font-bold tracking-tight text-foreground sm:text-4xl">Orders, all in one place.</h1>
            <p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Receipts for every booking, meal and Malaysian experience you have collected.</p>
          </div>
          <div className="flex flex-wrap items-center gap-2"><Link href={activityHref("itinerary")}><Button variant="outline" className="rounded-full border-primary/20 text-primary hover:bg-secondary">View itinerary</Button></Link><Link href="/customer/explore"><Button className="rounded-full bg-primary px-5 hover:bg-primary/90">Explore again</Button></Link></div>
        </header>

        <section className="mt-7 grid gap-3 sm:grid-cols-3">
          {[{ label: "Total orders", value: stats.total, icon: ReceiptText }, { label: "Paid or completed", value: stats.paid, icon: CircleCheck }, { label: "Orders with bookings", value: stats.bookings, icon: CalendarDays }].map(({ label, value, icon: Icon }) => <div key={label} className="rounded-2xl border border-border bg-white px-4 py-4 shadow-[0_8px_24px_rgba(1,0,102,0.06)]"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-slate-500">{label}</span><Icon size={16} className="text-primary" /></div><p className="mt-2 font-[family-name:var(--font-mono)] text-2xl font-bold text-foreground">{value}</p></div>)}
        </section>

        <section className="mt-7 rounded-2xl border border-border bg-white p-4 shadow-[0_8px_24px_rgba(1,0,102,0.06)] sm:p-5">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-center"><label className="relative min-w-0 flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search order ID, product or outlet" className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50/70 pl-10 pr-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-[rgba(1,0,102,0.12)]" /></label><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[0.14em] text-slate-400"><SlidersHorizontal size={15} /> Filter</div></div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><select value={status} onChange={(event) => setStatus(event.target.value as OrderFilterStatus)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-primary">{STATUS_OPTIONS.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select><select value={type} onChange={(event) => setType(event.target.value as OrderFilterType)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-primary"><option value="all">All order types</option><option value="booking">Bookings</option><option value="product">Products</option><option value="mixed">Mixed orders</option></select><select value={outletId} onChange={(event) => setOutletId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-primary"><option value="all">All outlets</option>{outlets.map((outlet) => <option key={outlet.id} value={outlet.id}>{outlet.name}</option>)}</select><input type="date" value={from} onChange={(event) => setFrom(event.target.value)} aria-label="Orders from date" className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-primary" /><input type="date" value={to} onChange={(event) => setTo(event.target.value)} aria-label="Orders to date" className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-primary" /></div>
          {hasFilters && <button type="button" onClick={clearFilters} className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline"><X size={13} /> Clear filters</button>}
        </section>

        {error && <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
        <div className="mt-7 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-slate-400">History</p><p className="mt-1 text-sm text-slate-500">{filteredOrders.length} {filteredOrders.length === 1 ? "order" : "orders"} found</p></div><span className="hidden items-center gap-1 text-xs text-slate-400 sm:inline-flex"><Clock3 size={14} /> Newest first</span></div>

        {filteredOrders.length === 0 ? <div className="mt-5"><EmptyState icon={<Package size={40} />} title={hasFilters ? "No orders match these filters" : "No orders yet"} description={hasFilters ? "Try clearing one filter or searching for another activity." : "Your booking and order history will show up here once you check out."} action={hasFilters ? <Button variant="outline" onClick={clearFilters}>Clear filters</Button> : <Link href="/customer/explore"><Button>Explore experiences</Button></Link>} /></div> : <>
          <div className="mt-4 space-y-3">{pagedOrders.map((order) => { const kind = orderType(order); const orderOutlets = [...new Set(order.items.map((item) => outletMap.get(item.outletId)?.name).filter(Boolean))]; const primaryItem = order.items.find((item) => item.imageUrl) ?? order.items[0]; return <Link key={order.id} href={`/customer/orders/${order.id}`} className="group block rounded-2xl border border-border bg-white p-4 shadow-[0_6px_20px_rgba(1,0,102,0.04)] transition hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-[0_12px_28px_rgba(1,0,102,0.1)] sm:p-5"><div className="flex items-start gap-3"><div className="relative mt-0.5 h-16 w-16 shrink-0 overflow-hidden rounded-xl bg-secondary text-primary">{primaryItem?.imageUrl ? <img src={primaryItem.imageUrl} alt={primaryItem.activityName} loading="lazy" className="h-full w-full object-cover" /> : <div className="flex h-full w-full items-center justify-center">{kind === "booking" ? <CalendarDays size={22} /> : kind === "mixed" ? <ReceiptText size={22} /> : <Package size={22} />}</div>}{order.items.length > 1 && <span className="absolute bottom-1 right-1 rounded-md bg-slate-900/75 px-1.5 py-0.5 text-[10px] font-bold text-white">+{order.items.length - 1}</span>}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-[family-name:var(--font-mono)] text-xs font-bold text-primary">{shortOrderId(order.id)}</span><span className="rounded-full bg-secondary px-2 py-1 text-[10px] font-bold uppercase tracking-wide text-primary">{typeLabel(kind)}</span><StatusBadge status={order.status} /></div><p className="mt-3 text-sm font-semibold leading-5 text-slate-800">{order.items.slice(0, 2).map((item) => `${item.qty}× ${item.activityName}`).join(" · ")}{order.items.length > 2 ? ` +${order.items.length - 2} more` : ""}</p><p className="mt-2 text-xs text-slate-500">{orderOutlets.join(" · ") || "MyWisata marketplace"} · {paymentLabel(order.paymentMethod)}</p></div><ChevronRight size={18} className="mt-1 shrink-0 text-slate-300 transition group-hover:translate-x-1 group-hover:text-primary" /></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-3 text-xs"><span className="text-slate-500">{dateLabel(order.createdAt)} · {order.items.reduce((sum, item) => sum + item.qty, 0)} items</span><span className="font-[family-name:var(--font-mono)] text-sm font-bold text-primary">RM {order.total.toFixed(2)}</span></div></Link>; })}</div>
          {pageCount > 1 && <nav aria-label="Order history pagination" className="mt-5 flex flex-col gap-3 rounded-2xl border border-border bg-white px-4 py-3 shadow-[0_6px_20px_rgba(1,0,102,0.04)] sm:flex-row sm:items-center sm:justify-between"><p className="text-xs text-slate-500">Showing {(visiblePage - 1) * PAGE_SIZE + 1}–{Math.min(visiblePage * PAGE_SIZE, filteredOrders.length)} of {filteredOrders.length} orders</p><div className="flex items-center justify-between gap-3 sm:justify-end"><button type="button" aria-label="Previous page" disabled={visiblePage === 1} onClick={() => setPage(Math.max(1, visiblePage - 1))} className="inline-flex h-9 items-center gap-1 rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600 transition hover:border-primary/30 hover:text-primary disabled:cursor-not-allowed disabled:opacity-40"><ChevronLeft size={15} /> Previous</button><span className="min-w-20 text-center text-xs font-semibold text-slate-500">Page {visiblePage} of {pageCount}</span><button type="button" aria-label="Next page" disabled={visiblePage === pageCount} onClick={() => setPage(Math.min(pageCount, visiblePage + 1))} className="inline-flex h-9 items-center gap-1 rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600 transition hover:border-primary/30 hover:text-primary disabled:cursor-not-allowed disabled:opacity-40">Next <ChevronRight size={15} /></button></div></nav>}
        </>}
      </div>
    </div>
  );
}

import { notFound } from 'next/navigation';
import type { Metadata } from 'next';
import { createClient } from '@/lib/supabase/server';

type Block = { id: string; type: string; title?: string; body?: string; image?: string; imageUrl?: string; cta?: string };
type GalleryItem = { url: string; alt?: string };

function normalizeBlocks(value: unknown): Block[] {
  return Array.isArray(value) ? value.filter((block): block is Block => Boolean(block && typeof block === 'object' && typeof (block as Block).id === 'string' && typeof (block as Block).type === 'string')) : [];
}

function normalizeGallery(value: unknown): GalleryItem[] {
  if (!Array.isArray(value)) return [];
  return value.map((item) => typeof item === 'string' ? { url: item } : item).filter((item): item is GalleryItem => Boolean(item && typeof item.url === 'string' && item.url));
}

function formatHours(hours: unknown) {
  if (!hours || typeof hours !== 'object') return 'Check the outlet schedule before booking.';
  const entries = Object.entries(hours as Record<string, unknown>).filter(([, value]) => value && typeof value === 'object');
  if (!entries.length) return 'Check the outlet schedule before booking.';
  return entries.map(([day, value]) => {
    const schedule = value as { open?: string; close?: string; closed?: boolean };
    return `${day.slice(0, 3).toUpperCase()}: ${schedule.closed ? 'Closed' : `${schedule.open || '—'}–${schedule.close || '—'}`}`;
  }).join(' · ');
}

async function getOutletPage(outletId: string) {
  const db = await createClient();
  return db.from('outlets').select('id,name,address,city,state,operating_hours,outlet_pages(hero_url,brand_colour,font_family,featured_ids,seo_title,seo_description,blocks,gallery)').eq('id', outletId).maybeSingle();
}

export async function generateMetadata({ params }: { params: Promise<{ outletId: string }> }): Promise<Metadata> {
  const { outletId } = await params;
  const { data } = await getOutletPage(outletId);
  const page = Array.isArray(data?.outlet_pages) ? data?.outlet_pages[0] : data?.outlet_pages;
  return { title: page?.seo_title || data?.name || 'MyWisata outlet', description: page?.seo_description || `Explore products and experiences at ${data?.name || 'this MyWisata outlet'}.` };
}

export default async function OutletShopPage({ params }: { params: Promise<{ outletId: string }> }) {
  const { outletId } = await params;
  const db = await createClient();
  const [{ data: outlet }, { data: page }] = await Promise.all([
    db.from('outlets').select('id,name,address,city,state,operating_hours').eq('id', outletId).maybeSingle(),
    db.from('outlet_pages').select('hero_url,brand_colour,font_family,featured_ids,seo_title,seo_description,blocks,gallery').eq('outlet_id', outletId).maybeSingle(),
  ]);
  if (!outlet) notFound();
  const blocks = normalizeBlocks(page?.blocks);
  const gallery = normalizeGallery(page?.gallery);
  const featuredIds = Array.isArray(page?.featured_ids) ? page.featured_ids : [];
  const { data: products } = featuredIds.length ? await db.from('products').select('id,name,base_price,cover_url').eq('outlet_id', outletId).eq('status', 'active').in('id', featuredIds) : { data: [] };
  const featuredProducts = [...(products || [])].sort((a, b) => featuredIds.indexOf(a.id) - featuredIds.indexOf(b.id));
  return <main className="min-h-screen" style={{ background: '#f8faf8', color: '#15332c', fontFamily: page?.font_family || 'Inter, sans-serif' }}><section className="relative overflow-hidden" style={{ backgroundColor: page?.brand_colour || '#0d5c4a' }}>{page?.hero_url && <img src={page.hero_url} alt="" className="absolute inset-0 h-full w-full object-cover opacity-35" />}<div className="relative mx-auto max-w-5xl px-6 py-24 text-white"><p className="text-xs font-semibold uppercase tracking-[0.2em] opacity-80">Verified MyWisata outlet</p><h1 className="mt-3 max-w-3xl text-4xl font-black tracking-tight sm:text-6xl">{outlet.name}</h1><p className="mt-4 max-w-2xl text-sm opacity-90">{outlet.address || [outlet.city, outlet.state].filter(Boolean).join(', ')}</p></div></section><div className="mx-auto max-w-5xl px-6 py-10"><div className="grid gap-6 md:grid-cols-2">{blocks.map((block) => <section key={block.id} className="rounded-2xl border border-emerald-100 bg-white p-6 shadow-sm"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-emerald-700">{block.type.replace('_', ' ')}</p><h2 className="mt-2 text-xl font-bold">{block.title || 'Discover this outlet'}</h2>{block.body && <p className="mt-2 text-sm leading-6 text-slate-600">{block.body}</p>}{(block.imageUrl || block.image) && <img src={block.imageUrl || block.image} alt={block.title || ''} className="mt-4 h-40 w-full rounded-xl object-cover" />}{block.type === 'hours' && <p className="mt-4 rounded-xl bg-amber-50 px-4 py-3 text-sm text-slate-700">{formatHours(outlet.operating_hours)}</p>}{block.type === 'contact' && <div className="mt-4 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-slate-700"><p>{outlet.address || [outlet.city, outlet.state].filter(Boolean).join(', ') || 'Malaysia'}</p><a className="mt-2 inline-block font-semibold text-emerald-800 hover:underline" href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([outlet.name, outlet.address, outlet.city, outlet.state].filter(Boolean).join(', '))}`} target="_blank" rel="noreferrer">Open directions</a></div>}{block.type === 'cta' && <a className="mt-4 inline-flex rounded-xl bg-emerald-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-emerald-800" href="#featured-products">{block.cta || 'Explore this outlet'}</a>}{block.type === 'product_grid' && <div id="featured-products" className="mt-4 grid gap-3 sm:grid-cols-2">{featuredProducts.map((product) => <a key={product.id} href={`/customer/activity/${product.id}`} className="overflow-hidden rounded-xl border border-emerald-100 bg-emerald-50/40 transition hover:-translate-y-0.5"><div className="h-28 bg-emerald-100">{product.cover_url && <img src={product.cover_url} alt={product.name} className="h-full w-full object-cover" />}</div><div className="p-3"><p className="truncate text-sm font-bold">{product.name}</p><p className="mt-1 text-xs font-semibold text-emerald-700">RM {Number(product.base_price).toFixed(2)}</p></div></a>)}</div>}</section>)}</div>{gallery.length > 0 && <section className="mt-8"><h2 className="text-xl font-bold">Gallery</h2><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3">{gallery.map((item) => <img key={item.url} src={item.url} alt={item.alt || `${outlet.name} gallery`} className="aspect-[4/3] w-full rounded-xl object-cover" />)}</div></section>}<section className="mt-8 rounded-2xl border border-amber-100 bg-amber-50 p-5"><h2 className="font-bold">Opening hours</h2><p className="mt-1 text-sm text-slate-700">{formatHours(outlet.operating_hours)}</p></section></div></main>;
}

"use client";

import { useState, useRef, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import {
  Phone, User, Camera, MessageSquare, ClipboardList,
  ShieldCheck, Upload, Loader2, ChevronRight, CheckCircle2,
} from "lucide-react";
import { useAuth } from "@/components/providers/auth";
import { useActionFeedback } from "@/components/providers/action-feedback";
import { Button } from "@/components/ui/button";

const STEPS = [
  { id: "phone",    label: "Phone" },
  { id: "identity", label: "Identity" },
  { id: "avatar",   label: "Avatar" },
  { id: "bio",      label: "Bio" },
  { id: "survey",   label: "Survey" },
] as const;

const INTERESTS = ["Adventure", "Culture", "Food", "Shopping", "Wellness", "Nature", "Art", "Sports", "Photography", "Nightlife"];

const TRAVEL_STYLES = [
  { value: "solo",   label: "Solo Traveller" },
  { value: "couple", label: "Couple" },
  { value: "family", label: "Family" },
  { value: "group",  label: "Group" },
] as const;

const BUDGET_RANGES = [
  { value: "budget",    label: "Budget (< RM 100/day)" },
  { value: "mid_range", label: "Mid-range (RM 100–500/day)" },
  { value: "luxury",    label: "Luxury (> RM 500/day)" },
] as const;

const MOBILITY_NEEDS = [
  { value: "none",       label: "No restrictions" },
  { value: "limited",    label: "Some restrictions" },
  { value: "wheelchair", label: "Wheelchair accessible required" },
] as const;

function initialStep(tier: string): number {
  if (tier === "email_verified") return 0;
  if (tier === "phone_verified") return 1;
  return -1;
}

export default function ProfilePage() {
  const { currentUser, refreshUser } = useAuth();
  const { showFeedback } = useActionFeedback();
  const router = useRouter();

  const tier = currentUser?.verificationTier ?? "email_verified";
  const startStep = tier === "email_verified" ? 0 : 1;
  const [step, setStep] = useState<number>(() => initialStep(tier));

  // ── Phone ──────────────────────────────────────────────────────────────────
  const [phonePhase, setPhonePhase] = useState<"enter" | "verify">("enter");
  const [phone, setPhone]           = useState("");
  const [otp,   setOtp]             = useState("");
  const [phoneError,  setPhoneError]  = useState<string | null>(null);
  const [phoneBusy,   setPhoneBusy]   = useState(false);

  // ── Identity ───────────────────────────────────────────────────────────────
  const [fullName, setFullName]         = useState(currentUser?.name !== currentUser?.email ? (currentUser?.name ?? "") : "");
  const [city,     setCity]             = useState(currentUser?.city ?? "");
  const [identityError, setIdentityError] = useState<string | null>(null);
  const [identityBusy,  setIdentityBusy]  = useState(false);

  // ── Avatar ─────────────────────────────────────────────────────────────────
  const fileRef = useRef<HTMLInputElement>(null);
  const [avatarFile,    setAvatarFile]    = useState<File | null>(null);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarError,   setAvatarError]   = useState<string | null>(null);
  const [avatarBusy,    setAvatarBusy]    = useState(false);

  useEffect(() => {
    return () => { if (avatarPreview) URL.revokeObjectURL(avatarPreview); };
  }, [avatarPreview]);

  // ── Bio ────────────────────────────────────────────────────────────────────
  const [bio,      setBio]      = useState("");
  const [bioError, setBioError] = useState<string | null>(null);
  const [bioBusy,  setBioBusy]  = useState(false);

  // ── Survey ─────────────────────────────────────────────────────────────────
  const [interests,     setInterests]     = useState<string[]>([]);
  const [travelStyle,   setTravelStyle]   = useState("solo");
  const [budgetRange,   setBudgetRange]   = useState("mid_range");
  const [mobilityNeeds, setMobilityNeeds] = useState("none");
  const [surveyError,   setSurveyError]   = useState<string | null>(null);
  const [surveyBusy,    setSurveyBusy]    = useState(false);

  // ── Phone handlers ─────────────────────────────────────────────────────────
  async function sendOtp() {
    if (!phone.trim()) { setPhoneError("Enter a phone number"); return; }
    setPhoneError(null);
    setPhoneBusy(true);
    try {
      const res = await fetch("/api/phone/send-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: phone.trim() }),
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to send OTP");
      }
      setPhonePhase("verify");
      showFeedback("success", "Verification code sent.");
    } catch (err) {
      setPhoneError(err instanceof Error ? err.message : "Failed to send OTP");
    } finally {
      setPhoneBusy(false);
    }
  }

  async function verifyOtp() {
    if (!otp.trim()) { setPhoneError("Enter the OTP code"); return; }
    setPhoneError(null);
    setPhoneBusy(true);
    try {
      const res = await fetch("/api/phone/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: phone.trim(), code: otp.trim() }),
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Invalid OTP");
      }
      await refreshUser();
      setStep(1);
      showFeedback("success", "Phone number verified.");
    } catch (err) {
      setPhoneError(err instanceof Error ? err.message : "Invalid OTP");
    } finally {
      setPhoneBusy(false);
    }
  }

  // ── Identity handler ───────────────────────────────────────────────────────
  async function submitIdentity() {
    if (!fullName.trim() || fullName.trim().length < 2) { setIdentityError("Full name must be at least 2 characters"); return; }
    if (!city.trim()) { setIdentityError("City is required"); return; }
    setIdentityError(null);
    setIdentityBusy(true);
    try {
      const res = await fetch("/api/profile/identity", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ fullName: fullName.trim(), city: city.trim(), country: "Malaysia" }),
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to save identity");
      }
      await refreshUser();
      setStep(2);
      showFeedback("success", "Identity details saved.");
    } catch (err) {
      setIdentityError(err instanceof Error ? err.message : "Failed to save identity");
    } finally {
      setIdentityBusy(false);
    }
  }

  // ── Avatar handlers ────────────────────────────────────────────────────────
  function handleFileSelect(file: File | null) {
    if (!file) return;
    const allowed = ["image/jpeg", "image/png", "image/webp"];
    if (!allowed.includes(file.type)) { setAvatarError("Only JPG, PNG, or WebP images are accepted"); return; }
    if (file.size > 2 * 1024 * 1024) { setAvatarError("Image must be under 2 MB"); return; }
    setAvatarError(null);
    setAvatarFile(file);
    if (avatarPreview) URL.revokeObjectURL(avatarPreview);
    setAvatarPreview(URL.createObjectURL(file));
  }

  async function submitAvatar() {
    if (!avatarFile) { setAvatarError("Please select a photo"); return; }
    setAvatarError(null);
    setAvatarBusy(true);
    try {
      const signRes = await fetch(`/api/profile/avatar?type=${encodeURIComponent(avatarFile.type)}`, { method: "PUT" });
      if (!signRes.ok) {
        const b = await signRes.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to get upload URL");
      }
      const { data: { uploadUrl, path } } = await signRes.json() as { data: { uploadUrl: string; path: string } };

      const uploadRes = await fetch(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": avatarFile.type },
        body: avatarFile,
      });
      if (!uploadRes.ok) throw new Error("Upload to storage failed");

      const confirmRes = await fetch("/api/profile/avatar/confirm", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path }),
      });
      if (!confirmRes.ok) {
        const b = await confirmRes.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to confirm avatar");
      }
      await refreshUser();
      setStep(3);
      showFeedback("success", "Profile photo updated.");
    } catch (err) {
      setAvatarError(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setAvatarBusy(false);
    }
  }

  // ── Bio handler ────────────────────────────────────────────────────────────
  async function submitBio() {
    if (bio.trim().length < 10) { setBioError("Bio must be at least 10 characters"); return; }
    setBioError(null);
    setBioBusy(true);
    try {
      const res = await fetch("/api/profile/bio", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bio: bio.trim() }),
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to save bio");
      }
      setStep(4);
      showFeedback("success", "Bio saved.");
    } catch (err) {
      setBioError(err instanceof Error ? err.message : "Failed to save bio");
    } finally {
      setBioBusy(false);
    }
  }

  // ── Survey handler ─────────────────────────────────────────────────────────
  async function submitSurvey() {
    if (interests.length === 0) { setSurveyError("Select at least one interest"); return; }
    setSurveyError(null);
    setSurveyBusy(true);
    try {
      const res = await fetch("/api/profile/survey", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ interests, travelStyle, budgetRange, mobilityNeeds }),
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error((b as any)?.error?.message ?? "Failed to submit survey");
      }
      await refreshUser();
      setStep(-1);
      showFeedback("success", "Travel preferences saved.");
    } catch (err) {
      setSurveyError(err instanceof Error ? err.message : "Failed to submit survey");
    } finally {
      setSurveyBusy(false);
    }
  }

  // ── Done state ─────────────────────────────────────────────────────────────
  const isDone = step === -1 || tier === "profile_complete" || tier === "kyc_verified";

  if (isDone) {
    return (
      <div className="max-w-2xl mx-auto px-4 sm:px-6 py-16 text-center">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-primary/15 mb-5">
          <ShieldCheck size={32} className="text-primary" />
        </div>
        <h1 className="text-2xl font-bold text-foreground mb-2">Profile Complete!</h1>
        <p className="text-sm text-muted-foreground mb-6">
          Your profile is set up. Submit your identity documents to unlock wallet withdrawals and full affiliate earnings.
        </p>
        <Button onClick={() => router.push("/customer/kyc")} className="gap-1.5">
          Proceed to KYC Verification <ChevronRight size={15} />
        </Button>
      </div>
    );
  }

  // ── Progress bar ───────────────────────────────────────────────────────────
  const visibleSteps = STEPS.slice(startStep);
  const currentProgress = step - startStep;

  return (
    <div className="max-w-2xl mx-auto px-4 sm:px-6 py-10">
      <h1 className="text-2xl font-bold text-foreground mb-1 font-[family-name:var(--font-display)]">
        Complete Your Profile
      </h1>
      <p className="text-sm text-muted-foreground mb-6">
        Finish all steps to unlock recommendation submissions and affiliate links.
      </p>

      {/* Progress */}
      <div className="flex items-end gap-1.5 mb-8">
        {visibleSteps.map(({ id, label }, i) => {
          const done   = i < currentProgress;
          const active = i === currentProgress;
          return (
            <div key={id} className="flex-1 flex flex-col items-center gap-1">
              <div
                className="w-full h-1.5 rounded-full transition-colors"
                style={{ backgroundColor: done || active ? "var(--primary)" : "var(--secondary)" }}
              />
              <span
                className="text-[10px] font-semibold"
                style={{ color: active ? "var(--primary)" : done ? "var(--primary)" : "var(--muted-foreground)", opacity: done ? 0.6 : 1 }}
              >
                {label}
              </span>
            </div>
          );
        })}
      </div>

      {/* ── Step 0: Phone Verification ───────────────────────────────────── */}
      {step === 0 && (
        <div className="rounded-2xl border border-border bg-card p-6 space-y-4">
          <div className="flex items-center gap-2">
            <Phone size={18} className="text-primary" />
            <h2 className="font-bold text-foreground">Verify Your Phone Number</h2>
          </div>

          {phonePhase === "enter" ? (
            <>
              <p className="text-xs text-muted-foreground">Enter your phone number in international format. We&apos;ll send a 6-digit OTP.</p>
              <div className="space-y-1">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Phone Number</label>
                <input
                  type="tel"
                  value={phone}
                  onChange={(e) => { setPhone(e.target.value); setPhoneError(null); }}
                  placeholder="+60123456789"
                  className="w-full px-3 py-2.5 text-sm rounded-xl border bg-background text-foreground outline-none focus:ring-2 focus:ring-primary/30"
                  style={{ borderColor: phoneError ? "var(--destructive)" : "var(--border)" }}
                />
                {phoneError && <p className="text-xs text-destructive">{phoneError}</p>}
              </div>
              <Button onClick={sendOtp} disabled={phoneBusy} className="w-full">
                {phoneBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
                {phoneBusy ? "Sending…" : "Send OTP"}
              </Button>
            </>
          ) : (
            <>
              <p className="text-xs text-muted-foreground">Enter the 6-digit code sent to <strong>{phone}</strong>.</p>
              <div className="space-y-1">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">OTP Code</label>
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={otp}
                  onChange={(e) => { setOtp(e.target.value); setPhoneError(null); }}
                  placeholder="123456"
                  className="w-full px-3 py-2.5 text-sm rounded-xl border bg-background text-foreground outline-none focus:ring-2 focus:ring-primary/30 tracking-widest text-center"
                  style={{ borderColor: phoneError ? "var(--destructive)" : "var(--border)" }}
                />
                {phoneError && <p className="text-xs text-destructive">{phoneError}</p>}
              </div>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => { setPhonePhase("enter"); setOtp(""); setPhoneError(null); }}
                >
                  Change Number
                </Button>
                <Button onClick={verifyOtp} disabled={phoneBusy} className="flex-1">
                  {phoneBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
                  {phoneBusy ? "Verifying…" : "Verify OTP"}
                </Button>
              </div>
            </>
          )}
        </div>
      )}

      {/* ── Step 1: Identity ─────────────────────────────────────────────── */}
      {step === 1 && (
        <div className="rounded-2xl border border-border bg-card p-6 space-y-4">
          <div className="flex items-center gap-2">
            <User size={18} className="text-primary" />
            <h2 className="font-bold text-foreground">Your Identity</h2>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Full Name</label>
            <input
              value={fullName}
              onChange={(e) => { setFullName(e.target.value); setIdentityError(null); }}
              placeholder="e.g. Ahmad Bin Ali"
              className="w-full px-3 py-2.5 text-sm rounded-xl border bg-background text-foreground outline-none focus:ring-2 focus:ring-primary/30"
              style={{ borderColor: identityError ? "var(--destructive)" : "var(--border)" }}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">City</label>
            <input
              value={city}
              onChange={(e) => { setCity(e.target.value); setIdentityError(null); }}
              placeholder="e.g. Kuala Lumpur"
              className="w-full px-3 py-2.5 text-sm rounded-xl border bg-background text-foreground outline-none focus:ring-2 focus:ring-primary/30"
              style={{ borderColor: identityError ? "var(--destructive)" : "var(--border)" }}
            />
          </div>
          {identityError && <p className="text-xs text-destructive">{identityError}</p>}
          <Button onClick={submitIdentity} disabled={identityBusy} className="w-full">
            {identityBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
            {identityBusy ? "Saving…" : "Continue"}
          </Button>
        </div>
      )}

      {/* ── Step 2: Avatar ───────────────────────────────────────────────── */}
      {step === 2 && (
        <div className="rounded-2xl border border-border bg-card p-6 space-y-4">
          <div className="flex items-center gap-2">
            <Camera size={18} className="text-primary" />
            <h2 className="font-bold text-foreground">Profile Photo</h2>
          </div>
          <p className="text-xs text-muted-foreground">Upload a clear photo of yourself. JPG, PNG, or WebP · max 2 MB.</p>
          <input
            ref={fileRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            className="hidden"
            onChange={(e) => handleFileSelect(e.target.files?.[0] ?? null)}
          />
          <button
            type="button"
            onClick={() => fileRef.current?.click()}
            className="w-full flex flex-col items-center justify-center gap-3 p-8 rounded-xl border-2 border-dashed transition-colors"
            style={{
              borderColor: avatarError ? "var(--destructive)" : avatarFile ? "var(--primary)" : "var(--border)",
              backgroundColor: avatarFile ? "color-mix(in srgb, var(--primary) 6%, transparent)" : "transparent",
            }}
          >
            {avatarPreview ? (
              <>
                <img src={avatarPreview} alt="preview" className="w-20 h-20 rounded-full object-cover border-2 border-primary" />
                <p className="text-xs text-muted-foreground">Click to change photo</p>
              </>
            ) : (
              <>
                <Upload size={24} className="text-muted-foreground" />
                <p className="text-sm text-muted-foreground">Click to upload photo</p>
              </>
            )}
          </button>
          {avatarError && <p className="text-xs text-destructive">{avatarError}</p>}
          <Button onClick={submitAvatar} disabled={avatarBusy || !avatarFile} className="w-full">
            {avatarBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
            {avatarBusy ? "Uploading…" : "Upload Photo"}
          </Button>
        </div>
      )}

      {/* ── Step 3: Bio ──────────────────────────────────────────────────── */}
      {step === 3 && (
        <div className="rounded-2xl border border-border bg-card p-6 space-y-4">
          <div className="flex items-center gap-2">
            <MessageSquare size={18} className="text-primary" />
            <h2 className="font-bold text-foreground">About You</h2>
          </div>
          <p className="text-xs text-muted-foreground">
            A short bio appears on your public profile and recommendation posts. Min 10, max 500 characters.
          </p>
          <div className="space-y-1">
            <textarea
              value={bio}
              onChange={(e) => { setBio(e.target.value); setBioError(null); }}
              placeholder="e.g. Malaysian travel enthusiast who loves discovering hidden gems and authentic local food…"
              rows={4}
              maxLength={500}
              className="w-full px-3 py-2.5 text-sm rounded-xl border bg-background text-foreground outline-none focus:ring-2 focus:ring-primary/30 resize-none"
              style={{ borderColor: bioError ? "var(--destructive)" : "var(--border)" }}
            />
            <div className="flex justify-between items-center">
              {bioError ? <p className="text-xs text-destructive">{bioError}</p> : <span />}
              <p className="text-xs text-muted-foreground">{bio.length}/500</p>
            </div>
          </div>
          <Button onClick={submitBio} disabled={bioBusy} className="w-full">
            {bioBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
            {bioBusy ? "Saving…" : "Continue"}
          </Button>
        </div>
      )}

      {/* ── Step 4: Survey ───────────────────────────────────────────────── */}
      {step === 4 && (
        <div className="rounded-2xl border border-border bg-card p-6 space-y-5">
          <div className="flex items-center gap-2">
            <ClipboardList size={18} className="text-primary" />
            <h2 className="font-bold text-foreground">Travel Preferences</h2>
          </div>
          <p className="text-xs text-muted-foreground">Help us personalise your experience with a quick survey.</p>

          <div className="space-y-2">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Interests (select all that apply)</p>
            <div className="flex flex-wrap gap-2">
              {INTERESTS.map((it) => {
                const key = it.toLowerCase();
                const sel = interests.includes(key);
                return (
                  <button
                    key={it}
                    type="button"
                    onClick={() => setInterests((prev) => sel ? prev.filter((x) => x !== key) : [...prev, key])}
                    className="px-3 py-1.5 text-xs font-semibold rounded-full border transition-colors"
                    style={{
                      backgroundColor: sel ? "var(--primary)" : "transparent",
                      borderColor:     sel ? "var(--primary)" : "var(--border)",
                      color:           sel ? "white"           : "var(--foreground)",
                    }}
                  >
                    {it}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="space-y-2">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Travel Style</p>
            <div className="grid grid-cols-2 gap-2">
              {TRAVEL_STYLES.map(({ value, label }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setTravelStyle(value)}
                  className="px-3 py-2 text-sm rounded-xl border transition-colors text-left"
                  style={{
                    backgroundColor: travelStyle === value ? "color-mix(in srgb, var(--primary) 12%, transparent)" : "transparent",
                    borderColor:     travelStyle === value ? "var(--primary)" : "var(--border)",
                    color:           travelStyle === value ? "var(--primary)" : "var(--foreground)",
                    fontWeight:      travelStyle === value ? 600 : 400,
                  }}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Budget Range</p>
            <div className="space-y-1.5">
              {BUDGET_RANGES.map(({ value, label }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setBudgetRange(value)}
                  className="w-full px-3 py-2 text-sm rounded-xl border transition-colors text-left flex items-center gap-2"
                  style={{
                    backgroundColor: budgetRange === value ? "color-mix(in srgb, var(--primary) 12%, transparent)" : "transparent",
                    borderColor:     budgetRange === value ? "var(--primary)" : "var(--border)",
                    color:           budgetRange === value ? "var(--primary)" : "var(--foreground)",
                    fontWeight:      budgetRange === value ? 600 : 400,
                  }}
                >
                  {budgetRange === value && <CheckCircle2 size={13} />}
                  {label}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Mobility Needs</p>
            <div className="space-y-1.5">
              {MOBILITY_NEEDS.map(({ value, label }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setMobilityNeeds(value)}
                  className="w-full px-3 py-2 text-sm rounded-xl border transition-colors text-left flex items-center gap-2"
                  style={{
                    backgroundColor: mobilityNeeds === value ? "color-mix(in srgb, var(--primary) 12%, transparent)" : "transparent",
                    borderColor:     mobilityNeeds === value ? "var(--primary)" : "var(--border)",
                    color:           mobilityNeeds === value ? "var(--primary)" : "var(--foreground)",
                    fontWeight:      mobilityNeeds === value ? 600 : 400,
                  }}
                >
                  {mobilityNeeds === value && <CheckCircle2 size={13} />}
                  {label}
                </button>
              ))}
            </div>
          </div>

          {surveyError && <p className="text-xs text-destructive">{surveyError}</p>}
          <Button onClick={submitSurvey} disabled={surveyBusy || interests.length === 0} className="w-full">
            {surveyBusy && <Loader2 size={14} className="animate-spin mr-1.5" />}
            {surveyBusy ? "Submitting…" : "Complete Profile"}
          </Button>
        </div>
      )}
    </div>
  );
}

