// Contract #5: single dispatch point for cross-domain effects.
// Mock impl: synchronous in-memory listeners + console log. Swap for a real
// bus later without touching callers.
import type { DomainEvent, DomainEventName } from "./types";

type Listener = (event: DomainEvent) => void;

const listeners = new Map<DomainEventName, Listener[]>();

export function on(name: DomainEventName, fn: Listener) {
  const list = listeners.get(name) ?? [];
  list.push(fn);
  listeners.set(name, list);
}

export function emit<T>(name: DomainEventName, payload: T) {
  const event: DomainEvent<T> = { name, payload, at: new Date().toISOString() };
  if (process.env.NODE_ENV !== "production") {
    // eslint-disable-next-line no-console
    console.log("[event]", name, payload);
  }
  for (const fn of listeners.get(name) ?? []) fn(event);
}

"use client";

import { useEffect, useRef, useState } from "react";
import { APIProvider, Circle, InfoWindow, Map, Marker, useApiIsLoaded, useMap } from "@vis.gl/react-google-maps";
import { MarkerClusterer } from "@googlemaps/markerclusterer";

export interface MapPin {
  id: string;
  lat: number;
  lng: number;
  label: string;
  sublabel?: string;
  href?: string;
}

function ApiLoadedNotifier({ onApiLoaded }: { onApiLoaded?: () => void }) {
  const loaded = useApiIsLoaded();
  useEffect(() => {
    if (loaded) onApiLoaded?.();
  }, [loaded, onApiLoaded]);
  return null;
}

function Recenter({ center, zoom }: { center: [number, number]; zoom: number }) {
  const map = useMap();
  useEffect(() => {
    if (!map) return;
    map.panTo({ lat: center[0], lng: center[1] });
    map.setZoom(zoom);
  }, [center[0], center[1], zoom, map]);
  return null;
}

function Markers({
  pins,
  cluster,
  selectedId,
  onSelect,
}: {
  pins: MapPin[];
  cluster?: boolean;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}) {
  const map = useMap();
  // Plain refs, not state: markers are read imperatively (by the clusterer and
  // the InfoWindow anchor) and must never themselves trigger a re-render.
  const markersRef = useRef<Record<string, google.maps.Marker>>({});
  const clustererRef = useRef<MarkerClusterer | null>(null);
  // Stable per-id callback refs: an inline `ref={m => ...}` gets a new identity
  // every render, so React detaches+reattaches it (null then marker) each time,
  // which caused an infinite render loop when that callback wrote to state.
  const refCallbacksRef = useRef<Record<string, (m: google.maps.Marker | null) => void>>({});

  // Classic Marker: no mapId/cloud config needed. Switch to AdvancedMarker +
  // a Map ID only if custom marker art is required later.
  useEffect(() => {
    if (!map || !cluster) return;
    clustererRef.current = new MarkerClusterer({ map });
    return () => {
      clustererRef.current?.clearMarkers();
      clustererRef.current = null;
    };
  }, [map, cluster]);

  function getRefCallback(id: string) {
    if (!refCallbacksRef.current[id]) {
      refCallbacksRef.current[id] = (marker: google.maps.Marker | null) => {
        if (marker) markersRef.current[id] = marker;
        else delete markersRef.current[id];

        if (cluster && clustererRef.current) {
          clustererRef.current.clearMarkers();
          clustererRef.current.addMarkers(Object.values(markersRef.current));
        }
      };
    }
    return refCallbacksRef.current[id];
  }

  const selectedPin = pins.find((p) => p.id === selectedId) ?? null;

  return (
    <>
      {pins.map((pin) => (
        <Marker
          key={pin.id}
          position={{ lat: pin.lat, lng: pin.lng }}
          title={pin.label}
          ref={getRefCallback(pin.id)}
          onClick={() => onSelect(pin.id)}
        />
      ))}
      {selectedPin && markersRef.current[selectedPin.id] && (
        <InfoWindow anchor={markersRef.current[selectedPin.id]} onCloseClick={() => onSelect(null)}>
          <div style={{ fontSize: 13, fontWeight: 600 }}>{selectedPin.label}</div>
          {selectedPin.sublabel && <div style={{ fontSize: 11, color: "#666" }}>{selectedPin.sublabel}</div>}
          {selectedPin.href && (
            <a href={selectedPin.href} style={{ fontSize: 11, fontWeight: 600, color: "var(--travel-blue)" }}>
              View details →
            </a>
          )}
        </InfoWindow>
      )}
    </>
  );
}

export function GoogleMap({
  pins,
  center,
  zoom = 11,
  height = 320,
  cluster,
  radiusCenter,
  radiusKm,
  onApiLoaded,
}: {
  pins: MapPin[];
  center: [number, number];
  zoom?: number;
  height?: number;
  cluster?: boolean;
  radiusCenter?: [number, number];
  radiusKm?: number;
  onApiLoaded?: () => void;
}) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;

  if (!apiKey) {
    return (
      <div
        className="flex items-center justify-center rounded-2xl bg-muted text-sm text-muted-foreground text-center px-4"
        style={{ height }}
      >
        Map unavailable — set NEXT_PUBLIC_GOOGLE_MAPS_API_KEY
      </div>
    );
  }

  return (
    <APIProvider apiKey={apiKey}>
      <Map
        defaultCenter={{ lat: center[0], lng: center[1] }}
        defaultZoom={zoom}
        gestureHandling="greedy"
        style={{ height, width: "100%", borderRadius: "1rem" }}
      >
        <ApiLoadedNotifier onApiLoaded={onApiLoaded} />
        <Recenter center={center} zoom={zoom} />
        <Markers pins={pins} cluster={cluster} selectedId={selectedId} onSelect={setSelectedId} />
        {radiusCenter && radiusKm && (
          <Circle
            center={{ lat: radiusCenter[0], lng: radiusCenter[1] }}
            radius={radiusKm * 1000}
            strokeColor="#010066"
            strokeOpacity={0.5}
            strokeWeight={1.5}
            fillColor="#010066"
            fillOpacity={0.06}
          />
        )}
      </Map>
    </APIProvider>
  );
}

"use client";

// Contract #1: AuthContext — { currentUser, roles, activeVendorId, activeOutletIds }.
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { setCurrentUserId } from "@/backend/domains/current-user";
import { createClient } from "@/lib/supabase/client";
import { pickDemoAssignment } from "@/lib/auth/demo-user-role";
import type { Role, User } from "@/backend/core/types";

interface AuthContextValue {
  currentUser: User | null;
  roles: Role[];
  activeVendorId?: string;
  activeOutletIds?: string[];
  loading: boolean;
  switchUser: (id: string, user?: User) => Promise<User | null>;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const supabase = useMemo(() => createClient(), []);

  const loadSupabaseUser = useCallback(async (authUserId: string) => {
    const { data: row, error } = await supabase
      .from("users")
      .select("id,email,full_name,city,phone,tier,user_roles(vendor_id,outlet_id,roles(name),outlets(vendor_id))")
      .eq("id", authUserId)
      .maybeSingle();
    if (error) throw error;

    const assignments = row?.user_roles ?? [];
    const assignment = pickDemoAssignment(assignments as Array<{ roles?: { name?: string | null } | { name?: string | null }[] | null }>) as typeof assignments[number] | undefined;
    const assignmentRole = Array.isArray(assignment?.roles) ? assignment.roles[0] : assignment?.roles;
    const assignmentOutlet = Array.isArray((assignment as any)?.outlets) ? (assignment as any).outlets[0] : (assignment as any)?.outlets;
    const vendorId = assignment?.vendor_id ?? assignmentOutlet?.vendor_id;
    const name = row?.full_name ?? row?.email ?? "User";
    const user: User | null = row ? {
      id: row.id,
      name,
      email: row.email,
      role: (assignmentRole?.name ?? "customer") as Role,
      avatarInitial: name[0]?.toUpperCase() ?? "?",
      city: row.city ?? undefined,
      phone: row.phone ?? undefined,
      verificationTier: (row.tier ?? "email_verified") as User["verificationTier"],
      vendorId: vendorId ?? undefined,
      outletId: assignment?.outlet_id ?? undefined,
    } : null;
    setCurrentUser(user ?? null);
    if (user) setCurrentUserId(authUserId);
    return user ?? null;
  }, [supabase]);

  useEffect(() => {
    let active = true;

    async function load() {
      const { data: { user } } = await supabase.auth.getUser();
      if (!active) return;
      if (!user) {
        // Do not trust the old localStorage-only demo selection. Server pages
        // authenticate through Supabase cookies, so both sides must agree.
        setCurrentUser(null);
        setLoading(false);
        return;
      }
      await loadSupabaseUser(user.id);
      if (active) setLoading(false);
    }

    load().catch(() => {
      if (!active) return;
      setCurrentUser(null);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (!session?.user) {
        setCurrentUser(null);
        setLoading(false);
        return;
      }
      loadSupabaseUser(session.user.id).finally(() => setLoading(false));
    });

    return () => {
      active = false;
      subscription.unsubscribe();
    };
  }, [loadSupabaseUser, supabase]);

  const switchUser = useCallback(async (id: string, selectedUser?: User) => {
    const user = selectedUser;
    if (!user || user.id !== id) throw new Error('Demo account is unavailable');

    const response = await fetch('/api/auth/demo-signin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: user.email }),
    });
    const result = await response.json() as { error?: string };
    if (!response.ok) throw new Error(result.error || 'Unable to sign in');

    const loadedUser = await loadSupabaseUser(id);
    setLoading(false);
    return loadedUser;
  }, [loadSupabaseUser]);

  const refreshUser = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) await loadSupabaseUser(user.id);
  }, [loadSupabaseUser, supabase]);

  const value: AuthContextValue = {
    currentUser,
    roles: currentUser ? [currentUser.role] : [],
    activeVendorId: currentUser?.vendorId,
    activeOutletIds: currentUser?.outletId ? [currentUser.outletId] : undefined,
    loading,
    switchUser,
    refreshUser,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}

/** Guards a route group: redirects to /login if the current user's role isn't allowed. */
export function useRequireRole(allowed: Role[]): AuthContextValue {
  const auth = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (auth.loading) return;
    if (!auth.currentUser || !allowed.includes(auth.currentUser.role)) {
      router.replace("/login");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [auth.loading, auth.currentUser?.role]);

  return auth;
}

