'use client';
// P4 — Member 4 owns this hook (D1 Cart)

import { useEffect, useState, useCallback } from 'react';
import type { CartSummary } from '@/types';
import { add, lineTotal } from '@/lib/money';

export function useCart() {
  const [cart,    setCart]    = useState<CartSummary | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchCart = useCallback(async () => {
    setLoading(true);
    // TODO P4/D1: call GET /api/cart
    const res = await fetch('/api/cart');
    const { data } = await res.json();

    if (!data) { setCart(null); setLoading(false); return; }

    const items = ((data.cart_items as Record<string, unknown>[]) ?? []).map(i => {
      const variant = i.product_variants as Record<string, unknown> | null;
      const slot    = i.booking_slots    as Record<string, unknown> | null;
      const product = (variant?.products ?? slot?.products) as Record<string, unknown> | null;
      return {
        id:          String(i.id),
        variantId:   i.variant_id ? String(i.variant_id) : null,
        slotId:      i.slot_id    ? String(i.slot_id)    : null,
        productName: String(product?.name ?? 'Unknown'),
        variantName: variant?.name ? String(variant.name) : null,
        outletName:  '',
        unitPrice:   Number(i.unit_price),
        quantity:    Number(i.quantity),
        lineTotal:   lineTotal(Number(i.unit_price), Number(i.quantity)),
        coverUrl:    product?.cover_url ? String(product.cover_url) : null,
        slotStartsAt: slot?.starts_at ? String(slot.starts_at) : null,
      };
    });

    const subtotal = items.reduce((s, i) => add(s, i.lineTotal), 0);

    setCart({ items, subtotal, discountAmount: 0, total: subtotal, appliedVoucherCode: null });
    setLoading(false);
  }, []);

  useEffect(() => { fetchCart(); }, [fetchCart]);

  async function addToCart(variantId?: string, slotId?: string, quantity = 1) {
    await fetch('/api/cart', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ variantId, slotId, quantity }),
    });
    await fetchCart();
  }

  async function checkout(paymentMethod: 'mock_card' | 'wallet', voucherCode?: string) {
    const res = await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ paymentMethod, voucherCode }),
    });
    return res.json();
  }

  return { cart, loading, addToCart, checkout, refetch: fetchCart };
}

import { createBrowserClient } from '@supabase/ssr';

// Singleton: multiple createBrowserClient() calls on the same storage key
// trigger Supabase's "Multiple GoTrueClient instances" warning and risk
// desynced sessions. Every browser caller must share this one instance.
let client: ReturnType<typeof createBrowserClient<any>> | undefined;

export function createClient() {
  if (!client) {
    client = createBrowserClient<any>(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    );
  }
  return client;
}

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';

export async function createClient() {
  const cookieStore = await cookies();

  // The checked-in database.ts is a hand-maintained approximation. The remote
  // Supabase schema is authoritative until `db:types` is run against the
  // linked project, so keep query relationships runtime-compatible here.
  return createServerClient<any>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() { return cookieStore.getAll(); },
        setAll(cookiesToSet: Array<{ name: string; value: string; options?: Record<string, unknown> }>) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options),
            );
          } catch {
            // Called from Server Component — cookies will be set by middleware
          }
        },
      },
    },
  );
}

// P-TMF (Trust & Money Flow) — Input validation schemas
// EVERY API route in this domain MUST pass request body through .parse() or .safeParse()
// before hitting the DB. Never trust `await request.json()` directly.

import { z } from 'zod';
import { validateReviewReason } from '@/lib/kyc/review-reasons';
import { KYC_REVIEW_REASON_CODES } from '@/lib/kyc/types';

// ── Common building blocks ─────────────────────────────────

const uuid    = z.string().regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i, 'Invalid UUID');
const rmMoney = z.number().finite().min(0.01).max(100_000).multipleOf(0.01);
const shortId = z.string().min(1).max(128);

// ── KYC ────────────────────────────────────────────────────

export const kycSubmitSchema = z.object({
  documentType: z.enum(['national_id', 'passport', 'driving_license']),
  documentUrl:  z.string().url().max(2000),
}).strict();

export const kycReviewSchema = z.object({
  userId: uuid,
  action: z.enum(['approve', 'reject', 'request_info']),
  reasonCode: z.enum(KYC_REVIEW_REASON_CODES).optional(),
  reasonDetail: z.string().max(500).optional(),
}).strict().superRefine((data, ctx) => {
  if (data.action === 'approve') {
    if (data.reasonCode !== undefined || data.reasonDetail !== undefined) {
      ctx.addIssue({ code: 'custom', message: 'Approved submissions cannot include a review reason', path: ['reasonCode'] });
    }
    return;
  }

  if (!data.reasonCode) {
    ctx.addIssue({ code: 'custom', message: 'A review reason code is required', path: ['reasonCode'] });
    return;
  }

  const validation = validateReviewReason(data.action, data.reasonCode, data.reasonDetail ?? null);
  if (!validation.ok) {
    ctx.addIssue({ code: 'custom', message: validation.error, path: [validation.error === 'reason_detail_too_short' ? 'reasonDetail' : 'reasonCode'] });
  }
});

// ── Vendor Recommendation ──────────────────────────────────

export const recommendationSubmitSchema = z.object({
  vendorName:    z.string().trim().min(3).max(255),
  vendorAddress: z.string().trim().max(500).optional(),
  description:   z.string().trim().min(20).max(2000),
  categoryId:    uuid.optional(),
}).strict();

export const recommendationReviewSchema = z.object({
  action: z.enum(['approve', 'reject']),
  reason: z.string().max(500).optional(),
}).strict();

export const recommendationConvertSchema = z.object({
  vendorId:    uuid,
  bonusAmount: rmMoney.optional().default(12.50),
}).strict();

// ── Wallet & Withdrawal ────────────────────────────────────

export const withdrawalSubmitSchema = z.object({
  amount:        rmMoney.min(10),   // minimum RM 10 withdrawal
  destinationId: uuid.optional(),
}).strict();

export const withdrawalApproveSchema = z.object({
  action: z.enum(['approve', 'reject', 'hold']),
  note:   z.string().max(500).optional(),
}).strict().refine(
  (data) => data.action !== 'reject' || (data.note && data.note.length >= 10),
  { message: 'Reject requires a note of at least 10 characters', path: ['note'] },
);

// ── Idempotency ────────────────────────────────────────────

export const idempotencyHeaderSchema = z.string().regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i).or(z.string().min(16).max(128));

// ── Response envelope ──────────────────────────────────────

export function apiOk<T>(data: T, init?: { status?: number }) {
  return Response.json({ data, error: null }, { status: init?.status ?? 200 });
}

export function apiFail(code: string, message: string, status = 400, details?: unknown) {
  return Response.json({ data: null, error: { code, message, details } }, { status });
}

/**
 * Parse and validate request body. On failure, returns a 422 response with
 * Zod's flattened error output — safe to return to client.
 */
export async function parseBody<T extends z.ZodTypeAny>(
  request: Request,
  schema: T,
): Promise<{ ok: true; data: z.infer<T> } | { ok: false; response: Response }> {
  let raw: unknown;
  try { raw = await request.json(); }
  catch { return { ok: false, response: apiFail('INVALID_JSON', 'Body is not valid JSON', 400) }; }

  const result = schema.safeParse(raw);
  if (!result.success) {
    return {
      ok: false,
      response: apiFail(
        'VALIDATION_FAILED',
        'Request body failed validation',
        422,
        result.error.flatten(),
      ),
    };
  }
  return { ok: true, data: result.data };
}

// Export inferred types for use in handlers
export type KycSubmit             = z.infer<typeof kycSubmitSchema>;
export type KycReview             = z.infer<typeof kycReviewSchema>;
export type RecommendationSubmit  = z.infer<typeof recommendationSubmitSchema>;
export type RecommendationReview  = z.infer<typeof recommendationReviewSchema>;
export type RecommendationConvert = z.infer<typeof recommendationConvertSchema>;
export type WithdrawalSubmit      = z.infer<typeof withdrawalSubmitSchema>;
export type WithdrawalApprove     = z.infer<typeof withdrawalApproveSchema>;

import { createClient } from '@/lib/supabase/server';
import { createServiceClient } from '@/lib/supabase/service';
import { apiFail } from '@/lib/validation/schemas';

export type VendorRole = 'vendor_owner' | 'outlet_manager';

export interface VendorAccess {
  userId: string;
  vendorId: string;
  role: VendorRole;
  outletIds: string[];
  isOwner: boolean;
  isOutletManager: boolean;
  authDb: any;
  serviceDb: any;
}

type AccessResult = { ok: true; access: VendorAccess } | { ok: false; response: Response };

function relation<T>(value: T | T[] | null | undefined): T | null {
  return Array.isArray(value) ? value[0] ?? null : value ?? null;
}

/**
 * Resolve the caller's role and data scope before any service-role query.
 * The service client is only returned after the caller is scoped to this vendor.
 */
export async function authorizeVendor(vendorId: string, allowedRoles: VendorRole[] = ['vendor_owner', 'outlet_manager']): Promise<AccessResult> {
  const authDb = await createClient() as any;
  const { data: { user } } = await authDb.auth.getUser();
  if (!user) return { ok: false, response: apiFail('UNAUTHORIZED', 'Sign in required', 401) };

  const { data: vendor, error: vendorError } = await authDb
    .from('vendors')
    .select('id,owner_id,status')
    .eq('id', vendorId)
    .maybeSingle();
  if (vendorError) return { ok: false, response: apiFail('DB_ERROR', vendorError.message, 500) };
  if (!vendor) return { ok: false, response: apiFail('NOT_FOUND', 'Vendor not found', 404) };
  if (vendor.status !== 'approved') return { ok: false, response: apiFail('INVALID_STATE', 'Vendor is not approved', 403) };

  if (vendor.owner_id === user.id && allowedRoles.includes('vendor_owner')) {
    const { data: outlets, error } = await authDb.from('outlets').select('id').eq('vendor_id', vendorId);
    if (error) return { ok: false, response: apiFail('DB_ERROR', error.message, 500) };
    return {
      ok: true,
      access: {
        userId: user.id,
        vendorId,
        role: 'vendor_owner',
        outletIds: (outlets || []).map((outlet: { id: string }) => outlet.id),
        isOwner: true,
        isOutletManager: false,
        authDb,
        serviceDb: createServiceClient() as any,
      },
    };
  }

  if (!allowedRoles.includes('outlet_manager')) {
    return { ok: false, response: apiFail('FORBIDDEN', 'Vendor owner permission required', 403) };
  }

  const { data: assignments, error: assignmentError } = await authDb
    .from('outlet_managers')
    .select('outlet_id,outlets(vendor_id)')
    .eq('user_id', user.id);
  if (assignmentError) return { ok: false, response: apiFail('DB_ERROR', assignmentError.message, 500) };

  const outletIds: string[] = (assignments || [])
    .filter((assignment: any) => {
      const outletVendorId = relation<{ vendor_id: string }>(assignment.outlets)?.vendor_id;
      return outletVendorId === vendorId && Boolean(assignment.outlet_id);
    })
    .map((assignment: any) => String(assignment.outlet_id));

  if (!outletIds.length) return { ok: false, response: apiFail('FORBIDDEN', 'You are not assigned to an outlet in this vendor', 403) };

  return {
    ok: true,
    access: {
      userId: user.id,
      vendorId,
      role: 'outlet_manager',
      outletIds: [...new Set(outletIds)],
      isOwner: false,
      isOutletManager: true,
      authDb,
      serviceDb: createServiceClient() as any,
    },
  };
}

export async function authorizeOutlet(vendorId: string, outletId: string, allowedRoles: VendorRole[] = ['vendor_owner', 'outlet_manager']) {
  const result = await authorizeVendor(vendorId, allowedRoles);
  if (!result.ok) return result;
  if (!result.access.outletIds.includes(outletId)) {
    return { ok: false as const, response: apiFail('FORBIDDEN', 'This outlet is outside your assigned scope', 403) };
  }
  return result;
}

import { createClient } from '@/lib/supabase/server';
import { createServiceClient } from '@/lib/supabase/service';
import type { RecentOrder } from '@/components/vendor/recent-transactions';
import { outletLocation, outletShortName } from '@/lib/outlet-display';

export type DashboardFilter = 'today' | '7d' | '30d' | '12m' | 'custom';
export type DashboardCustomRange = { from?: string; to?: string };

type DashboardRow = {
  id: string;
  order_id: string;
  outlet_id: string;
  product_id: string | null;
  product_name: string;
  quantity: number;
  line_total: number;
